import type { AdvancedQuestion, AdvancedStep } from "../advanced-lessons";

// sqr rota las opciones según `shift` para que la respuesta correcta no quede
// siempre en el mismo índice (evita el patrón "la correcta siempre es A").
const sqr = (prompt: string, correct: string, wrongA: string, wrongB: string, wrongC: string, shift: number, why: string, code = ""): AdvancedQuestion => {
  const all = [correct, wrongA, wrongB, wrongC];
  const options = all.map((_, k) => all[(k + shift) % 4]);
  const answer = (4 - shift) % 4;
  return { prompt, options, answer, why, code };
};

const stepsN09: AdvancedStep[] = [
 {id:"n09-dockerfile",title:"Dockerfile para .NET",summary:"Un Dockerfile define cómo construir la imagen de una app .NET. Para producción se usa un build multi-stage: una etapa con la imagen SDK (pesada, con el compilador) compila y publica, y una etapa final copia solo el resultado sobre una imagen runtime (ligera, sin SDK). Esto reduce drásticamente el tamaño final y la superficie de ataque.",code:"FROM mcr.microsoft.com/dotnet/sdk:8.0 AS build\nWORKDIR /src\nCOPY . .\nRUN dotnet restore\nRUN dotnet publish -c Release -o /app/publish\n\nFROM mcr.microsoft.com/dotnet/aspnet:8.0 AS final\nWORKDIR /app\nCOPY --from=build /app/publish .\nENTRYPOINT [\"dotnet\", \"MiApi.dll\"]",questions:[
  sqr("¿Por qué un Dockerfile de producción para .NET usa dos imágenes base distintas (SDK y runtime)?","Para compilar con la imagen SDK y ejecutar con la imagen runtime, más pequeña y sin herramientas de build","Porque .NET no permite compilar y ejecutar en la misma imagen bajo ninguna circunstancia","Porque la imagen runtime no puede copiar archivos de otra etapa","Porque Docker exige al menos dos FROM en todo Dockerfile",0,"El patrón multi-stage separa la etapa de compilación (SDK, pesada) de la etapa final de ejecución (runtime, ligera), reduciendo tamaño y superficie de ataque de la imagen publicada."),
  sqr("En el Dockerfile de ejemplo, ¿qué hace `COPY --from=build /app/publish .`?","Copia los artefactos ya publicados de la etapa 'build' hacia la etapa final","Copia el código fuente completo del repositorio a la imagen final","Instala el SDK de .NET en la imagen final","Ejecuta dotnet publish dentro de la imagen final",0,"`--from=build` referencia la etapa anterior por su alias (AS build) y copia solo los archivos ya publicados, sin arrastrar el SDK ni el código fuente."),
  sqr("¿Qué imagen base es apropiada para la etapa final de una API ASP.NET Core en producción?","mcr.microsoft.com/dotnet/aspnet:8.0","mcr.microsoft.com/dotnet/sdk:8.0","mcr.microsoft.com/dotnet/runtime:8.0 (para una API web)","ubuntu:latest sin runtime de .NET",0,"La imagen 'aspnet' incluye el ASP.NET Core Runtime necesario para hospedar apps web; 'runtime' a secas solo trae el runtime base de .NET, insuficiente para ASP.NET Core sin instalar dependencias extra."),
  sqr("¿Qué instrucción define el comando que se ejecuta cuando arranca el contenedor?","ENTRYPOINT","WORKDIR","COPY","FROM",1,"ENTRYPOINT (o CMD) especifica el proceso principal del contenedor; aquí lanza 'dotnet MiApi.dll'."),
  sqr("¿Por qué conviene copiar y restaurar solo los archivos .csproj antes de copiar todo el código fuente en un Dockerfile bien optimizado?","Para aprovechar la caché de capas de Docker: si el código cambia pero no las dependencias, no se repite el restore","Porque Docker no permite copiar archivos .cs directamente","Porque dotnet restore falla si hay archivos .cs presentes","Porque reduce el tamaño de la imagen final automáticamente",1,"Docker cachea cada capa; si primero se copian solo los .csproj y se hace restore, esa capa se reutiliza mientras las dependencias no cambien, aunque el código fuente sí cambie en builds posteriores."),
  sqr("¿Qué problema tiene construir la imagen final directamente desde `mcr.microsoft.com/dotnet/sdk:8.0` en vez de usar multi-stage?","La imagen final queda innecesariamente grande, con el compilador y herramientas que no se necesitan en producción","No es posible instalar ASP.NET Core sobre la imagen SDK","El contenedor no podría exponer puertos","dotnet publish no funciona dentro de una imagen SDK",2,"La imagen SDK es varias veces más grande que la runtime porque incluye compilador, MSBuild y herramientas; usarla en producción desperdicia espacio y aumenta la superficie de ataque sin beneficio."),
  sqr("¿Qué hace la instrucción WORKDIR en un Dockerfile?","Define el directorio de trabajo dentro del contenedor para las instrucciones siguientes","Crea un volumen persistente en el host","Define la red del contenedor","Expone un puerto del contenedor",3,"WORKDIR establece (y crea si no existe) el directorio actual dentro de la imagen para COPY, RUN y el comando final."),
  sqr("Si el Dockerfile no publica en modo Release, ¿qué consecuencia tiene en producción?","La app se ejecuta sin las optimizaciones de compilación pensadas para producción","No compila en absoluto","El contenedor no puede iniciar","Docker rechaza construir la imagen",0,"Sin -c Release, dotnet publish usa Debug por defecto en muchos flujos, generando binarios sin las optimizaciones de release, lo cual es indeseable en producción."),
  sqr("¿Qué instrucción de Docker se usa para declarar que el contenedor escucha en un puerto (documentación, no publicación real)?","EXPOSE","PORT","LISTEN","BIND",0,"EXPOSE documenta el puerto en el que la app escucha dentro del contenedor; la publicación real hacia el host se hace con `-p` al ejecutar `docker run`."),
  sqr("Trampa de entrevista: ¿EXPOSE en el Dockerfile hace que el puerto sea accesible desde fuera del host automáticamente?","No, EXPOSE es solo documentación; el mapeo real se hace con `docker run -p host:contenedor`","Sí, EXPOSE abre el puerto automáticamente hacia internet","Sí, pero solo en Docker Compose","No, EXPOSE bloquea el puerto por seguridad",0,"Un error común es creer que EXPOSE publica el puerto. En realidad solo documenta la intención; sin `-p` (o `ports:` en Compose) el puerto no es alcanzable desde el host."),
 ]},
 {id:"n09-docker-compose",title:"Docker Compose",summary:"Docker Compose es una herramienta para definir y ejecutar aplicaciones multi-contenedor en desarrollo local (por ejemplo una API, una base de datos y Redis) mediante un archivo YAML declarativo. No es un orquestador de producción como Kubernetes: no gestiona failover automático, escalado entre nodos ni actualizaciones rolling en un clúster.",code:"services:\n  api:\n    build: .\n    ports:\n      - \"8080:80\"\n    environment:\n      - ConnectionStrings__Default=Server=db;Database=App;User Id=sa;Password=Pass123!\n    depends_on:\n      - db\n  db:\n    image: mcr.microsoft.com/mssql/server:2022-latest\n    environment:\n      - ACCEPT_EULA=Y\n      - MSSQL_SA_PASSWORD=Pass123!\n    ports:\n      - \"1433:1433\"",questions:[
  sqr("¿Para qué sirve principalmente Docker Compose?","Definir y levantar varios contenedores relacionados (por ejemplo API + base de datos) en desarrollo local con un solo archivo","Orquestar contenedores entre múltiples servidores físicos en producción con failover automático","Reemplazar completamente a Kubernetes en clústeres de producción a gran escala","Compilar imágenes Docker sin necesidad de un Dockerfile",0,"Compose orquesta múltiples contenedores localmente a partir de un docker-compose.yml; para orquestación de producción a escala se usan herramientas como Kubernetes."),
  sqr("En el docker-compose.yml de ejemplo, ¿qué logra `depends_on: - db` en el servicio api?","Que Docker inicie el contenedor db antes de iniciar api (sin garantizar que db ya esté listo para aceptar conexiones)","Que api y db compartan el mismo proceso","Que db se destruya automáticamente cuando api se detenga","Que api pueda acceder a variables de entorno de db automáticamente",0,"depends_on controla el orden de arranque de contenedores, pero no espera a que el servicio interno (por ejemplo SQL Server) esté realmente listo para recibir conexiones; para eso se necesitan healthchecks o reintentos en la app."),
  sqr("¿Qué significa el mapeo `\"8080:80\"` en la sección ports del servicio api?","El puerto 8080 del host redirige al puerto 80 dentro del contenedor","El puerto 80 del host redirige al puerto 8080 del contenedor","Ambos puertos quedan bloqueados hasta configurar un firewall","Compose ignora el primer número y usa solo el segundo",0,"La sintaxis es `host:contenedor`; el tráfico que llega al puerto 8080 de la máquina host se reenvía al puerto 80 dentro del contenedor."),
  sqr("Dentro de la red creada por Docker Compose, ¿cómo puede el servicio api alcanzar al servicio db?","Usando el nombre del servicio (db) como si fuera un hostname, gracias a la resolución DNS interna de Compose","Solo mediante la IP pública del host","Nunca directamente, se requiere un proxy externo","Usando siempre 'localhost' desde dentro del contenedor api",0,"Compose crea una red donde cada servicio es resoluble por su nombre; por eso la cadena de conexión usa 'Server=db' en vez de una IP fija."),
  sqr("¿Es correcto afirmar que Docker Compose gestiona el escalado automático entre múltiples máquinas físicas como lo hace Kubernetes?","No, Compose está pensado para desarrollo/pruebas locales en una sola máquina, no para orquestación distribuida de producción","Sí, Compose y Kubernetes son intercambiables en cualquier escenario","Sí, Compose reemplaza a Kubernetes desde la versión 3 del archivo","No, porque Compose solo puede ejecutar un contenedor a la vez",0,"Es una trampa de entrevista común confundir ambas herramientas: Compose orquesta contenedores localmente; Kubernetes orquesta clústeres de producción con escalado, self-healing y despliegues distribuidos."),
  sqr("¿Qué comando levanta todos los servicios definidos en docker-compose.yml en segundo plano?","docker compose up -d","docker compose start-all","docker run compose","docker compose build --detach",0,"`docker compose up -d` crea y arranca los contenedores definidos, en modo detached (segundo plano)."),
  sqr("¿Qué representa la clave `build: .` en el servicio api del ejemplo?","Que la imagen de ese servicio se construye a partir del Dockerfile en el directorio actual, en vez de usar una imagen ya publicada","Que Compose construye automáticamente una base de datos","Que el servicio no requiere una imagen Docker","Que Compose descarga la imagen desde Docker Hub obligatoriamente",0,"`build: .` indica a Compose que construya la imagen usando el Dockerfile encontrado en ese contexto, a diferencia de `image:` que usa una imagen ya existente."),
  sqr("¿Qué comando detiene y elimina los contenedores, redes (y opcionalmente volúmenes) creados por Compose?","docker compose down","docker compose stop-all","docker compose remove","docker compose kill --clean",0,"`docker compose down` detiene los contenedores y elimina los recursos creados (contenedores, red); con `-v` también elimina volúmenes."),
  sqr("¿Qué riesgo de seguridad ilustra el ejemplo al declarar `MSSQL_SA_PASSWORD` directamente en el YAML?","Las credenciales quedan en texto plano en el archivo, lo cual es inapropiado para producción; deberían venir de secretos o variables externas","Ninguno, Docker Compose cifra automáticamente las variables de entorno","Solo es riesgoso si el archivo se sube a un repositorio privado","MSSQL_SA_PASSWORD no puede definirse mediante variables de entorno",0,"Hardcodear contraseñas en el docker-compose.yml es una mala práctica; en producción deben inyectarse mediante secretos, un archivo .env excluido del control de versiones, o un gestor de secretos."),
  sqr("Trampa de entrevista: ¿Docker Compose es adecuado como solución de orquestación para un entorno de producción de alta disponibilidad?","No necesariamente: para producción con alta disponibilidad y escalado se prefieren orquestadores como Kubernetes o servicios PaaS gestionados","Sí, siempre es la mejor opción para producción sin importar la escala","No, porque Compose no puede ejecutar más de un contenedor","Sí, porque Compose se ejecuta automáticamente en múltiples servidores",0,"Aunque Compose puede usarse en algunos despliegues simples de un solo host, su diseño y ecosistema están orientados a desarrollo y pruebas locales; alta disponibilidad real suele requerir un orquestador de clúster."),
 ]},
 {id:"n09-env-vars",title:"Variables de entorno",summary:"ASP.NET Core lee configuración desde múltiples fuentes (appsettings.json, variables de entorno, argumentos de línea de comandos), combinándolas en un único IConfiguration. Para expresar jerarquía en variables de entorno (que no soportan los dos puntos de appsettings.json) se usa doble guion bajo `__` como separador, por ejemplo `ConnectionStrings__Default` equivale a `ConnectionStrings:Default` en JSON.",code:"// appsettings.json\n// { \"ConnectionStrings\": { \"Default\": \"...\" } }\n\n// Variable de entorno equivalente:\n// ConnectionStrings__Default=Server=db;Database=App;...\n\nvar builder = WebApplication.CreateBuilder(args);\nstring? cs = builder.Configuration[\"ConnectionStrings:Default\"];",questions:[
  sqr("¿Qué separador usa ASP.NET Core en el nombre de una variable de entorno para representar jerarquía de configuración?","Doble guion bajo `__`","Dos puntos `:`","Un solo guion bajo `_`","Una barra `/`",0,"Los dos puntos funcionan en claves de configuración en memoria/JSON, pero muchos shells no permiten `:` en nombres de variables de entorno; por eso el proveedor de entorno usa `__` como separador jerárquico."),
  sqr("¿Qué variable de entorno sobrescribe correctamente el valor de `appsettings.json` `{ \"ConnectionStrings\": { \"Default\": \"X\" } }`?","ConnectionStrings__Default=Y","ConnectionStrings:Default=Y","ConnectionStrings.Default=Y","ConnectionStringsDefault=Y",0,"El proveedor de variables de entorno traduce `__` a `:` internamente, por lo que `ConnectionStrings__Default` mapea a la clave `ConnectionStrings:Default`."),
  sqr("Dado `builder.Configuration[\"ConnectionStrings:Default\"]` y una variable de entorno `ConnectionStrings__Default` definida en el contenedor, ¿qué valor se lee en tiempo de ejecución?","El valor de la variable de entorno, porque normalmente se agrega después que appsettings.json en el pipeline de configuración y tiene mayor prioridad","Siempre el valor de appsettings.json, las variables de entorno se ignoran en contenedores","Ambos valores se concatenan","Ninguno; hay que usar IOptions obligatoriamente para leer variables de entorno",0,"El host por defecto agrega proveedores en orden (appsettings, appsettings.{Environment}, variables de entorno, argumentos), y las fuentes agregadas después sobrescriben claves iguales de fuentes anteriores; env vars normalmente se agregan después de los archivos JSON."),
  sqr("¿Por qué es una buena práctica inyectar secretos (como contraseñas de base de datos) mediante variables de entorno en contenedores en vez de escribirlos en appsettings.json?","Porque appsettings.json suele versionarse en el repositorio, exponiendo el secreto; las variables de entorno pueden inyectarse solo en el entorno de ejecución","Porque las variables de entorno son más rápidas de leer en tiempo de ejecución","Porque appsettings.json no admite cadenas de conexión","Porque ASP.NET Core no permite leer secretos desde JSON",0,"appsettings.json normalmente se versiona con el código; los secretos deben mantenerse fuera del control de versiones e inyectarse en tiempo de despliegue mediante variables de entorno o un gestor de secretos."),
  sqr("¿Qué patrón fuertemente tipado se usa habitualmente en ASP.NET Core para consumir una sección de configuración como una clase C#?","El patrón Options (IOptions<T> / IOptionsSnapshot<T>) junto con `builder.Services.Configure<T>(...)`","Reflection manual sobre IConfiguration en cada controlador","Variables estáticas globales pobladas en Main","Atributos [FromEnv] en los modelos",0,"El patrón Options permite mapear una sección de configuración a una clase POCO fuertemente tipada, inyectable vía DI como IOptions<T>."),
  sqr("¿Qué ocurre si el nombre de una variable de entorno usa un solo guion bajo en vez de doble, por ejemplo `ConnectionStrings_Default`?","No se interpretará como una clave jerárquica; ASP.NET Core buscará una clave llamada literalmente 'ConnectionStrings_Default', no 'ConnectionStrings:Default'","Funciona exactamente igual que con doble guion bajo","Provoca un error de arranque de la aplicación","Se interpreta como un array de configuración",0,"Solo el separador exacto `__` (doble guion bajo) se traduce a `:`; un solo guion bajo se trata como parte literal del nombre de la clave, sin jerarquía."),
  sqr("¿Cuál es una trampa común al usar variables de entorno para arrays en configuración, por ejemplo `Cors:AllowedOrigins:0` y `Cors:AllowedOrigins:1`?","Se deben usar índices numéricos consecutivos, así: `Cors__AllowedOrigins__0` y `Cors__AllowedOrigins__1`","No es posible representar arrays mediante variables de entorno","Se deben separar los valores con comas en una sola variable siempre","Los arrays solo funcionan si vienen de appsettings.json",0,"El proveedor de configuración por entorno soporta arrays usando índices numéricos como segmento de la jerarquía, igual que en JSON."),
  sqr("¿Qué proveedor de configuración suele tener mayor prioridad por defecto en ASP.NET Core: appsettings.json o los argumentos de línea de comandos?","Los argumentos de línea de comandos, porque el host los agrega al final de la cadena de proveedores por convención","appsettings.json siempre gana sobre cualquier otra fuente","Ambos tienen exactamente la misma prioridad y se genera un error si difieren","Depende únicamente del sistema operativo",0,"El orden por defecto de CreateBuilder agrega los argumentos de línea de comandos al final, dándoles la mayor precedencia sobre archivos JSON y variables de entorno para la misma clave."),
  sqr("En Docker Compose, ¿cuál es una forma habitual de definir variables de entorno para un servicio sin hardcodearlas en el YAML?","Usar un archivo `.env` referenciado por Compose o la clave `env_file:`","Es obligatorio escribir cada valor literal en `environment:`","Variables de entorno no pueden usarse dentro de Compose","Solo se pueden definir mediante `docker exec` después de iniciar el contenedor",0,"Compose permite `env_file:` para cargar variables desde un archivo separado (habitualmente excluido del control de versiones), evitando hardcodear secretos en el YAML."),
  sqr("Trampa de entrevista: ¿es seguro asumir que toda variable de entorno definida en el sistema operativo host se propaga automáticamente dentro de un contenedor Docker?","No; solo las variables explícitamente pasadas con `-e`, `--env-file` o declaradas en `environment:`/`env_file:` de Compose llegan al contenedor","Sí, todas las variables del host siempre se copian automáticamente al contenedor","Sí, pero solo si el contenedor corre como root","No, los contenedores nunca pueden recibir variables de entorno del host",0,"Un contenedor está aislado; solo recibe las variables de entorno que se le pasan explícitamente al crearlo (via `docker run -e`, `--env-file`, o las secciones equivalentes de Compose)."),
 ]},
 {id:"n09-cicd",title:"CI/CD",summary:"CI/CD automatiza el ciclo de vida del software: integración continua (compilar y ejecutar pruebas en cada cambio para detectar errores temprano) y entrega/despliegue continuo (empaquetar y llevar la app a un entorno de forma automática y repetible). Un pipeline típico para una app .NET tiene etapas de restore, build, test, publish y deploy, fallando rápido si alguna etapa falla.",code:"# Ejemplo simplificado de pipeline (YAML genérico)\nsteps:\n  - run: dotnet restore\n  - run: dotnet build --configuration Release --no-restore\n  - run: dotnet test --configuration Release --no-build\n  - run: dotnet publish -c Release -o ./publish\n  - run: docker build -t miapi:${{ github.sha }} .\n  - run: docker push miapi:${{ github.sha }}",questions:[
  sqr("¿Qué significa la 'CI' de CI/CD en el contexto de un pipeline para una app .NET?","Integración continua: compilar y ejecutar pruebas automáticamente en cada cambio subido al repositorio","Configuración interna, un paso manual de revisión de código","Copiar e instalar dependencias de forma continua sin pruebas","Un sinónimo exacto de despliegue continuo",0,"CI (Continuous Integration) automatiza build y pruebas en cada commit/PR para detectar errores de integración lo antes posible."),
  sqr("En el pipeline de ejemplo, ¿por qué `dotnet test` se ejecuta con `--no-build`?","Porque el build ya se realizó en el paso anterior y repetirlo sería redundante y más lento","Porque dotnet test no puede compilar código nunca","Porque --no-build salta la ejecución de las pruebas","Porque el proyecto no tiene pruebas unitarias",0,"Encadenar --no-restore y --no-build en pasos sucesivos evita recompilar innecesariamente, reutilizando lo ya construido en el paso de build."),
  sqr("¿Qué diferencia hay entre 'entrega continua' (continuous delivery) y 'despliegue continuo' (continuous deployment)?","En entrega continua el paso a producción requiere una aprobación manual; en despliegue continuo se libera a producción automáticamente tras pasar el pipeline","Son términos idénticos sin ninguna diferencia práctica","Entrega continua no incluye pruebas automatizadas","Despliegue continuo nunca incluye pruebas",0,"Ambos automatizan hasta tener un artefacto desplegable; la diferencia clave está en si el último salto a producción es manual (delivery) o automático (deployment)."),
  sqr("¿Por qué es importante que el pipeline falle inmediatamente ('fail fast') si `dotnet test` encuentra pruebas rotas?","Para evitar publicar o desplegar un artefacto con errores conocidos detectados antes del deploy","Porque dotnet publish borra las pruebas fallidas automáticamente","Porque los pipelines no pueden tener más de un paso tras un fallo","No es importante, el deploy corrige los errores automáticamente",0,"Detener el pipeline ante un fallo evita que código roto llegue a etapas posteriores (publish, deploy), protegiendo la calidad del artefacto final."),
  sqr("¿Qué ventaja aporta usar `${{ github.sha }}` (o equivalente) como tag de la imagen Docker en el pipeline, en vez de usar siempre `latest`?","Cada build produce una imagen identificable y trazable a un commit específico, facilitando rollback y auditoría","Reduce el tamaño de la imagen Docker","Hace innecesario ejecutar pruebas","Evita tener que hacer docker push",0,"Etiquetar con el hash del commit (u otro identificador único) permite rastrear exactamente qué código contiene cada imagen y volver a una versión anterior con precisión."),
  sqr("¿Qué etapa del pipeline de ejemplo genera los artefactos listos para ejecutar en el destino final?","dotnet publish -c Release -o ./publish","dotnet restore","dotnet build --configuration Release --no-restore","docker push",1,"publish produce los binarios optimizados que luego se empaquetan (por ejemplo dentro de la imagen Docker) para el despliegue."),
  sqr("¿Qué diferencia principal hay entre `dotnet build` y `dotnet publish` en un pipeline de CI/CD?","build compila para verificar que el código es correcto; publish genera los artefactos finales listos para desplegar","Son exactamente el mismo comando en un pipeline","build siempre incluye el paso de deploy","publish no requiere haber compilado antes",0,"build valida que el código compila (útil junto con test); publish produce el resultado empaquetado que se despliega, incluyendo solo lo necesario en runtime."),
  sqr("¿Qué es una 'quality gate' típica dentro de un pipeline de CI/CD?","Una condición automática (como cobertura mínima de pruebas o cero vulnerabilidades críticas) que debe cumplirse para continuar el pipeline","Un servidor físico donde se aloja el código fuente","Un tipo de contenedor Docker especial","Una etapa opcional que nunca bloquea el pipeline",0,"Las quality gates son verificaciones automatizadas (cobertura, análisis estático, seguridad) que bloquean el avance del pipeline si no se cumplen umbrales definidos."),
  sqr("Trampa de entrevista: si `dotnet restore` falla por falta de conectividad a NuGet, ¿debería el pipeline continuar igualmente hacia build y deploy?","No; el pipeline debe detenerse en ese paso, ya que las etapas siguientes dependen de que restore haya completado exitosamente","Sí, build puede compensar un restore fallido","Sí, siempre y cuando el deploy use una imagen anterior en caché","No importa, restore es un paso opcional que puede omitirse siempre",0,"Cada etapa suele depender de que la anterior haya tenido éxito; continuar tras un restore fallido probablemente produce errores en cascada o, peor, un despliegue con dependencias desactualizadas."),
  sqr("¿Qué práctica reduce el riesgo de que un despliegue automático rompa producción, dentro de una estrategia CI/CD madura?","Ejecutar el pipeline completo (build, test, análisis) en cada pull request antes de fusionar a la rama principal","Desplegar directamente a producción sin ejecutar pruebas para ahorrar tiempo","Omitir el build en Release y desplegar solo binarios Debug","Ejecutar las pruebas únicamente una vez por semana",0,"Ejecutar el pipeline en cada PR detecta problemas antes de integrarlos a la rama principal, reduciendo el riesgo de que código roto llegue a producción."),
 ]},
 {id:"n09-health-probes",title:"Health probes",summary:"ASP.NET Core ofrece Health Checks (paquete Microsoft.Extensions.Diagnostics.HealthChecks) para exponer el estado de la app en un endpoint HTTP. En orquestadores de contenedores se distinguen liveness probes (¿el proceso sigue vivo? si falla, se reinicia el contenedor) de readiness probes (¿la app está lista para recibir tráfico? si falla, se deja de enrutar tráfico sin reiniciar el contenedor).",code:"var builder = WebApplication.CreateBuilder(args);\nbuilder.Services.AddHealthChecks()\n    .AddSqlServer(connectionString, name: \"db\")\n    .AddCheck(\"self\", () => HealthCheckResult.Healthy());\n\nvar app = builder.Build();\napp.MapHealthChecks(\"/health/live\", new HealthCheckOptions { Predicate = r => r.Name == \"self\" });\napp.MapHealthChecks(\"/health/ready\");\napp.Run();",questions:[
  sqr("¿Cuál es la diferencia principal entre una liveness probe y una readiness probe?","Liveness indica si el proceso sigue vivo y debe reiniciarse si falla; readiness indica si la app puede recibir tráfico en este momento, sin implicar reinicio","Son sinónimos exactos usados indistintamente","Liveness solo aplica a bases de datos; readiness solo aplica a APIs","Readiness siempre reinicia el contenedor si falla",0,"Liveness responde '¿sigue vivo el proceso?' (fallo -> reinicio); readiness responde '¿puede atender tráfico ahora?' (fallo -> se saca temporalmente de la rotación de balanceo, sin reiniciar)."),
  sqr("En el ejemplo, ¿por qué `/health/live` usa `Predicate = r => r.Name == \"self\"` mientras que `/health/ready` no filtra checks?","Para que la liveness solo verifique que el proceso responde (sin depender de servicios externos como la base de datos), mientras que readiness sí valida dependencias externas antes de aceptar tráfico","Porque `/health/live` no puede tener más de un check registrado por limitación del framework","Porque el orden de registro de AddHealthChecks determina cuál endpoint usa cada check automáticamente","Porque Predicate solo funciona en el endpoint de liveness",0,"Un patrón común es que liveness excluya dependencias externas (para no reiniciar el contenedor por una base de datos caída), y readiness sí incluya esas dependencias para dejar de enrutar tráfico si no están disponibles."),
  sqr("¿Qué consecuencia tendría que un liveness probe dependiera de la disponibilidad de la base de datos externa?","Si la base de datos cae, el orquestador podría reiniciar repetidamente contenedores sanos que no pueden arreglar el problema de la base de datos","Ninguna, es la configuración recomendada siempre","El contenedor se detendría permanentemente sin reintentos","Mejoraría el tiempo de respuesta del contenedor",0,"Reiniciar el proceso de la app no soluciona una base de datos caída; puede generar un bucle de reinicios inútil ('crash loop') que empeora la disponibilidad en vez de mejorarla."),
  sqr("¿Qué método de extensión registra el middleware que expone endpoints de health checks en ASP.NET Core?","app.MapHealthChecks(ruta, opciones)","app.UseRouting().Health()","builder.Services.MapHealth()","app.AddHealthEndpoint()",0,"MapHealthChecks mapea una ruta HTTP a la ejecución de los health checks registrados, opcionalmente filtrados con HealthCheckOptions.Predicate."),
  sqr("¿Qué código HTTP suele devolver un endpoint de health checks cuando el estado es 'Unhealthy'?","503 Service Unavailable","200 OK siempre, sin importar el estado","404 Not Found","301 Redirect",0,"Por convención, un estado Unhealthy produce 503, señalando a balanceadores/orquestadores que ese destino no debe recibir tráfico."),
  sqr("¿Qué diferencia hay entre los estados Healthy, Degraded y Unhealthy en el sistema de Health Checks de ASP.NET Core?","Healthy indica funcionamiento normal, Degraded indica que funciona pero con problemas parciales, y Unhealthy indica que el componente no funciona","Son tres nombres equivalentes para el mismo estado","Degraded siempre detiene el contenedor igual que Unhealthy","Solo existen dos estados posibles: Healthy y Unhealthy",0,"HealthStatus define tres niveles: Healthy, Degraded (funciona parcialmente, por ejemplo alta latencia) y Unhealthy (no funcional), permitiendo respuestas más matizadas que un simple sí/no."),
  sqr("¿Qué método se usa para registrar un chequeo de salud personalizado con una función lambda simple, como en el ejemplo `AddCheck(\"self\", ...)`?","AddCheck","AddSqlServer","AddCustomProbe","RegisterHealth",0,"AddCheck permite registrar un IHealthCheck ad-hoc (por ejemplo mediante una función delegate) sin crear una clase completa."),
  sqr("¿Por qué en Kubernetes conviene tener readiness y liveness como endpoints separados en vez de uno solo?","Porque cada probe responde a una pregunta distinta (vivo vs listo) y mezclar ambas puede causar reinicios innecesarios por fallos que solo afectan a la disponibilidad de tráfico","Porque Kubernetes no permite reutilizar el mismo puerto para dos rutas","Porque cada endpoint debe estar en un contenedor distinto","No hay ninguna razón práctica, es solo convención estética",0,"Separar los endpoints permite que Kubernetes reaccione de forma distinta según la probe: reiniciar el pod (liveness) o simplemente sacarlo de la rotación de servicio (readiness), sin confundir ambos casos."),
  sqr("¿Qué implica que un pod en Kubernetes falle su readiness probe repetidamente, a diferencia de fallar su liveness probe?","El pod deja de recibir tráfico nuevo pero sigue corriendo (no se reinicia) hasta que vuelva a pasar la probe","El pod se elimina inmediatamente y no se vuelve a crear","El clúster completo se marca como no disponible","Kubernetes reinicia automáticamente el nodo físico",0,"Un fallo de readiness solo afecta el enrutamiento de tráfico hacia ese pod; el proceso sigue vivo y puede recuperarse sin necesidad de reinicio, a diferencia de un fallo de liveness."),
  sqr("Trampa de entrevista: ¿es buena práctica que el endpoint de liveness ejecute consultas costosas contra múltiples servicios externos en cada llamada?","No; liveness debe ser una verificación barata y rápida de que el proceso responde, evitando dependencias externas costosas que puedan causar falsos negativos y reinicios innecesarios","Sí, cuanto más exhaustivo sea el chequeo de liveness, mejor siempre","Sí, porque así se detectan más problemas antes de escalar","No importa el costo, Kubernetes solo llama liveness una vez por despliegue",0,"Un liveness caro o dependiente de servicios externos puede fallar por razones ajenas al proceso mismo, provocando reinicios innecesarios ('crash loops'); debe ser una verificación ligera del propio proceso."),
 ]},
 {id:"n09-prod-logs",title:"Logs en producción",summary:"En producción conviene usar logging estructurado (mensajes con datos como propiedades nombradas, no solo texto libre concatenado) para poder filtrar, correlacionar y analizar logs a gran escala. ASP.NET Core integra ILogger<T> de forma nativa, y librerías como Serilog permiten enriquecer y enviar logs estructurados a sistemas centralizados (por ejemplo Application Insights, Seq o ELK).",code:"public class OrdersController : ControllerBase {\n  private readonly ILogger<OrdersController> _logger;\n  public OrdersController(ILogger<OrdersController> logger) => _logger = logger;\n\n  [HttpPost]\n  public IActionResult Create(Order order) {\n    _logger.LogInformation(\"Orden {OrderId} creada para cliente {CustomerId}\", order.Id, order.CustomerId);\n    return Ok();\n  }\n}",questions:[
  sqr("¿Qué ventaja tiene `_logger.LogInformation(\"Orden {OrderId} creada\", order.Id)` frente a `_logger.LogInformation($\"Orden {order.Id} creada\")`?","La primera crea logging estructurado: OrderId queda como propiedad consultable por separado; la segunda produce solo texto interpolado sin estructura","No hay ninguna diferencia real entre ambas formas","La segunda es más eficiente porque evita el uso de placeholders","La primera solo funciona si order.Id es string",0,"Con placeholders con nombre ({OrderId}), el proveedor de logging conserva cada valor como una propiedad estructurada, permitiendo búsquedas y filtros precisos en el sistema de logs centralizado; la interpolación de cadenas pierde esa estructura."),
  sqr("¿Qué interfaz genérica es la forma estándar de obtener un logger vinculado a una clase específica en ASP.NET Core mediante DI?","ILogger<T>","ILoggerFactory únicamente sin genérico","Console estático","ILogProvider<T>",0,"ILogger<T> se inyecta con el nombre de categoría igual al nombre completo del tipo T, facilitando filtrar logs por origen."),
  sqr("¿Por qué usar niveles de log (Trace, Debug, Information, Warning, Error, Critical) en vez de escribir todo como texto plano en la consola?","Permiten filtrar el volumen de logs por severidad y ajustar el nivel mínimo por entorno (por ejemplo más verboso en desarrollo, menos en producción)","Los niveles de log no afectan el rendimiento ni el volumen de datos","Solo existen dos niveles reales en .NET: Info y Error","Los niveles de log son exclusivos de Serilog y no existen en ASP.NET Core nativo",0,"Los niveles permiten controlar cuánta información se captura según el entorno, evitando ruido excesivo en producción mientras se conserva la capacidad de elevar la verbosidad al depurar un incidente."),
  sqr("¿Qué es 'correlación de logs' en una app distribuida (por ejemplo con múltiples microservicios)?","La capacidad de relacionar logs de distintos servicios que pertenecen a la misma solicitud, típicamente mediante un identificador de trazabilidad compartido (trace/correlation id)","Un sinónimo de nivel de log Critical","Un mecanismo que elimina automáticamente logs duplicados","Una función exclusiva de bases de datos relacionales",0,"Un identificador de correlación (por ejemplo TraceIdentifier o un header propagado entre servicios) permite reconstruir el flujo completo de una solicitud a través de múltiples servicios en los logs."),
  sqr("¿Por qué escribir contraseñas, tokens o números de tarjeta directamente en los logs de producción es una mala práctica?","Porque los logs suelen almacenarse y ser accesibles a más personas/sistemas de lo debido, exponiendo datos sensibles y violando buenas prácticas de seguridad y cumplimiento","Porque ASP.NET Core bloquea automáticamente cualquier log con esos datos","Porque los logs se eliminan automáticamente tras 24 horas si contienen datos sensibles","No es un problema real si el logger usa nivel Debug",0,"Los sistemas de logging centralizados suelen tener retención larga y acceso amplio; loguear secretos o PII expone datos sensibles innecesariamente y puede violar regulaciones de cumplimiento."),
  sqr("¿Qué patrón de configuración permite tener niveles de log distintos en Development y Production sin cambiar código?","Usar appsettings.Development.json y appsettings.Production.json (o variables de entorno) con distinta configuración de 'Logging:LogLevel'","Compilar dos binarios distintos, uno para cada entorno","Modificar el código fuente de ILogger en cada entorno","No es posible variar el nivel de log entre entornos en ASP.NET Core",0,"ASP.NET Core carga appsettings.{Environment}.json automáticamente según ASPNETCORE_ENVIRONMENT, permitiendo distinta verbosidad de logging por entorno sin recompilar."),
  sqr("¿Qué ventaja adicional aporta una librería como Serilog sobre el logging básico de ILogger?","Sinks configurables para enviar logs estructurados a múltiples destinos (archivo, Seq, Application Insights, Elasticsearch, etc.) con enriquecimiento adicional","Serilog reemplaza completamente la necesidad de niveles de log","Serilog solo funciona fuera de ASP.NET Core","Serilog elimina la necesidad de usar ILogger<T> en el código",0,"Serilog se integra con la abstracción ILogger de .NET y añade 'sinks' configurables para enviar los logs estructurados a múltiples destinos, además de enriquecedores de contexto."),
  sqr("En un contenedor Docker en producción, ¿cuál es una práctica común para el manejo de logs de la app?","Escribir los logs a stdout/stderr y dejar que la plataforma de orquestación/logging los recolecte centralizadamente","Escribir siempre los logs únicamente a un archivo local dentro del contenedor efímero","Deshabilitar el logging por completo para ahorrar recursos","Enviar los logs por correo electrónico en cada solicitud",0,"El patrón habitual en contenedores es loguear a stdout/stderr; el runtime de contenedores o un agente recolector se encarga de centralizar esos logs, evitando depender del sistema de archivos efímero del contenedor."),
  sqr("¿Qué significa que escribir un archivo de log dentro del sistema de archivos de un contenedor sea una mala práctica para producción?","El sistema de archivos del contenedor es efímero: si el contenedor se destruye o se reemplaza, los logs guardados solo ahí se pierden","Los contenedores no permiten escribir archivos bajo ninguna circunstancia","Escribir archivos dentro del contenedor ralentiza la red del clúster","Es una práctica recomendada sin ningún inconveniente",0,"Los contenedores son efímeros por diseño: al reiniciarse o reemplazarse (por ejemplo en un despliegue nuevo), el sistema de archivos local se pierde salvo que se use un volumen persistente; por eso se prefiere stdout/stderr o un backend externo."),
  sqr("Trampa de entrevista: ¿es equivalente usar `Console.WriteLine` para depurar en producción a usar `ILogger` con niveles y sinks configurados?","No; Console.WriteLine no respeta niveles de log, no se puede filtrar ni enrutar a sistemas centralizados, y complica el diagnóstico en producción a gran escala","Sí, ambos producen exactamente el mismo resultado operativo en producción","Sí, porque ambos escriben a la consola del contenedor","No, porque Console.WriteLine es más rápido que ILogger en todos los casos",0,"Aunque Console.WriteLine puede terminar en stdout igual que algunos sinks de ILogger, carece de niveles, estructura, filtrado y enrutamiento configurable, lo que lo hace inadecuado como estrategia de logging de producción."),
 ]},
 {id:"n09-azure-app-service",title:"Azure App Service",summary:"Azure App Service es un servicio PaaS (plataforma como servicio) totalmente administrado para hospedar aplicaciones web, APIs y contenedores sin gestionar servidores directamente. Sus deployment slots permiten desplegar una nueva versión en un slot separado (por ejemplo 'staging'), probarla, y luego hacer un swap con producción de forma prácticamente instantánea y con posibilidad de revertir, logrando despliegues de cero (o mínimo) downtime.",code:"# Azure CLI: crear un slot de staging y desplegar\naz webapp deployment slot create --name miapi --resource-group rg1 --slot staging\naz webapp deploy --resource-group rg1 --name miapi --slot staging --src-path ./publish.zip\n\n# Swap staging <-> production\naz webapp deployment slot swap --resource-group rg1 --name miapi --slot staging --target-slot production",questions:[
  sqr("¿Qué tipo de servicio en la nube es Azure App Service?","PaaS: una plataforma administrada donde se despliega la app sin gestionar el sistema operativo o el servidor subyacente","IaaS puro, donde el usuario administra manualmente las máquinas virtuales","SaaS, un software terminado listo para el usuario final","Solo un servicio de almacenamiento de archivos estáticos",0,"App Service es PaaS: Azure gestiona el sistema operativo, el runtime y el escalado subyacente, dejando al desarrollador enfocarse en desplegar y configurar la app."),
  sqr("¿Qué logra un 'swap' entre el slot 'staging' y el slot 'production' en App Service?","Intercambia el contenido y la configuración de ambos slots casi instantáneamente, permitiendo probar en staging y pasar a producción con downtime mínimo","Elimina permanentemente el slot de staging","Duplica el tráfico entre ambos slots simultáneamente para siempre","Reinicia la máquina virtual subyacente completa",0,"El swap intercambia los contenidos (y en general la configuración no marcada como 'sticky') entre los dos slots, permitiendo validar una versión nueva antes de que reciba tráfico de producción, con posibilidad de revertir haciendo otro swap."),
  sqr("¿Qué ventaja principal aportan los deployment slots frente a desplegar directamente sobre el slot de producción?","Permiten probar la nueva versión en un entorno idéntico antes del swap, reduciendo downtime y riesgo de un despliegue fallido visible para los usuarios","Los slots eliminan por completo la necesidad de pruebas automatizadas","Los slots reducen el costo de la suscripción de Azure automáticamente","Los slots son obligatorios para poder usar HTTPS",0,"Sin slots, el despliegue reemplaza directamente la app en producción, con riesgo de downtime o de exponer una versión con errores; con slots, la validación ocurre antes de que el tráfico de producción se vea afectado."),
  sqr("¿Qué configuración puede marcarse como 'sticky' (sticky settings) en un slot de App Service para que NO se intercambie durante un swap?","Ciertas variables de configuración y cadenas de conexión que deben permanecer específicas de cada slot, como la cadena de conexión de producción","El código de la aplicación siempre","El sistema operativo del App Service Plan","El nombre del recurso de Azure",0,"Las 'sticky settings' permiten que ciertas configuraciones (por ejemplo, apuntar a bases de datos distintas para staging y producción) no se muevan durante el swap, evitando que producción termine apuntando accidentalmente a recursos de staging."),
  sqr("¿Qué recurso de Azure define la capacidad de cómputo (tamaño de VM, número de instancias) sobre la que corre una App Service?","El App Service Plan","El Resource Group","El Deployment Slot","El Application Insights",0,"El App Service Plan determina el tier (Free, Basic, Standard, Premium...) y los recursos de cómputo compartidos por las apps alojadas en él."),
  sqr("¿Qué permite el escalado horizontal ('scale out') en Azure App Service?","Aumentar el número de instancias de la app para repartir la carga, en vez de aumentar los recursos de una sola instancia","Aumentar el tamaño de una única VM sin agregar instancias","Cambiar el lenguaje de programación de la app automáticamente","Reducir automáticamente la latencia de red entre regiones",0,"El escalado horizontal (scale out) agrega más instancias en paralelo; el escalado vertical (scale up) aumenta los recursos (CPU/RAM) de una instancia; App Service soporta ambos."),
  sqr("¿App Service puede desplegar directamente una imagen Docker en lugar de solo código publicado tradicionalmente?","Sí, App Service soporta contenedores Linux/Windows además del despliegue de código directo","No, App Service solo admite despliegue de binarios .NET sin contenedores","Sí, pero únicamente contenedores de bases de datos","No, para contenedores es obligatorio usar Azure Kubernetes Service",0,"App Service for Containers permite ejecutar una imagen Docker (propia o desde un registro como Azure Container Registry) como el hosting de la app."),
  sqr("¿Qué comando de Azure CLI del ejemplo realiza el intercambio entre el slot de staging y producción?","az webapp deployment slot swap","az webapp deploy --slot swap","az webapp slot exchange","az webapp deployment slot create --swap",0,"`az webapp deployment slot swap` con --slot y --target-slot ejecuta el intercambio de contenido/configuración entre los dos slots indicados."),
  sqr("Si el swap a producción revela un problema grave inmediatamente después de aplicarse, ¿qué acción de bajo riesgo puede tomarse en App Service?","Hacer un swap inverso para restaurar rápidamente la versión anterior a producción","Es imposible revertir un swap una vez realizado","Hay que borrar la App Service completa y recrearla desde cero","Solo se puede revertir editando manualmente cada archivo en producción",0,"Como el swap es esencialmente un intercambio, repetirlo en sentido inverso restaura rápidamente el estado anterior, siendo una de las razones clave por las que los slots reducen el riesgo de despliegue."),
  sqr("Trampa de entrevista: ¿un swap entre slots implica downtime equivalente a detener y volver a arrancar la aplicación desde cero?","No; el objetivo del swap es minimizar el downtime, ya que la instancia del slot destino ya está 'caliente' (arrancada y con warm-up) antes del intercambio","Sí, un swap siempre implica el mismo downtime que un despliegue directo tradicional","Sí, porque Azure apaga ambos slots durante el swap","No hay ninguna diferencia entre swap y un despliegue normal en cuanto a downtime",0,"Una de las ventajas centrales de los slots es que la app en el slot de destino ya está inicializada (incluyendo warm-up configurable) antes del swap, logrando una transición de tráfico prácticamente sin downtime perceptible."),
 ]},
 {id:"n09-challenge",title:"Reto de despliegue",summary:"Reto integrador del módulo: combina Dockerfile multi-stage, Docker Compose para desarrollo local, configuración por variables de entorno con separador `__`, un pipeline de CI/CD con etapas claras, health probes de liveness/readiness, logging estructurado en producción y despliegue con slots en Azure App Service.",code:"# Flujo integrador\n# 1) docker build (multi-stage) -> imagen ligera\n# 2) docker compose up -d (dev local: api + db)\n# 3) pipeline CI/CD: restore -> build -> test -> publish -> deploy\n# 4) /health/live y /health/ready expuestos\n# 5) logs estructurados a stdout\n# 6) az webapp deployment slot swap staging -> production",questions:[
  sqr("¿Por qué un Dockerfile de producción para una API .NET no debería basarse únicamente en la imagen SDK para la etapa final?","Porque incluiría herramientas de compilación innecesarias, aumentando tamaño y superficie de ataque frente a usar la imagen runtime/aspnet en la etapa final","Porque la imagen SDK no puede ejecutar aplicaciones compiladas bajo ninguna circunstancia","Porque Docker prohíbe usar la misma imagen en dos etapas","Porque la imagen SDK no soporta ENTRYPOINT",0,"El patrón multi-stage compila con SDK y ejecuta con una imagen runtime más pequeña, evitando cargar herramientas de build en la imagen que corre en producción."),
  sqr("¿Cuál es la diferencia central entre lo que orquesta Docker Compose y lo que orquesta un sistema como Kubernetes?","Compose coordina contenedores en desarrollo/pruebas locales; Kubernetes orquesta clústeres de producción con escalado y self-healing distribuido","Son exactamente equivalentes en alcance y propósito","Compose solo puede ejecutar un contenedor; Kubernetes ejecuta contenedores ilimitados","Kubernetes no puede usar imágenes construidas con Docker",0,"Compose está pensado para levantar servicios relacionados localmente; Kubernetes gestiona clústeres de producción con capacidades de escalado, recuperación automática y despliegues distribuidos."),
  sqr("¿Qué variable de entorno traduce correctamente la clave de configuración `Logging:LogLevel:Default` para un contenedor?","Logging__LogLevel__Default","Logging:LogLevel:Default (igual, sin cambios)","Logging.LogLevel.Default","LOGGING_LOGLEVEL_DEFAULT (con guion simple)",0,"El proveedor de configuración por entorno usa doble guion bajo `__` para representar cada nivel de jerarquía equivalente a los dos puntos `:`."),
  sqr("En el pipeline de CI/CD, ¿qué ocurre si `dotnet test` falla pero el pipeline continúa igualmente hacia `docker push`?","Se corre el riesgo de publicar y potencialmente desplegar una imagen con código que no pasa las pruebas conocidas","Es la práctica recomendada porque las pruebas no deben bloquear despliegues","dotnet test nunca puede fallar si el build fue exitoso","docker push automáticamente revierte cambios de código con pruebas fallidas",0,"Un pipeline bien diseñado debe detenerse ('fail fast') ante pruebas rotas, evitando publicar artefactos que no cumplen la calidad mínima verificada."),
  sqr("¿Por qué conviene que el endpoint de liveness (`/health/live`) no dependa de la base de datos, mientras que readiness (`/health/ready`) sí puede depender de ella?","Para evitar reinicios innecesarios del contenedor cuando el problema es externo (la base de datos), mientras que readiness sí debe reflejar si la app puede atender tráfico dependiente de esa base de datos","Porque liveness no puede tener ningún check registrado nunca","Porque ambos endpoints deben comportarse siempre exactamente igual","Porque readiness se ejecuta con menor frecuencia que liveness por diseño del framework",0,"Un liveness dependiente de servicios externos puede causar 'crash loops' cuando la falla es ajena al proceso; readiness sí debe considerar dependencias porque determina si conviene enrutar tráfico hacia esa instancia."),
  sqr("¿Por qué escribir logs estructurados con placeholders con nombre (`{OrderId}`) es preferible a interpolar cadenas en producción?","Porque conserva cada dato como una propiedad consultable en el sistema de logs centralizado, facilitando búsquedas y correlación","Porque reduce el tamaño físico del ejecutable compilado","Porque es la única forma soportada por ILogger de registrar strings","Porque evita por completo la necesidad de niveles de log",0,"El logging estructurado retiene los valores como campos indexables/consultables en vez de texto plano, mejorando el análisis y la correlación de eventos en producción."),
  sqr("¿Qué beneficio aporta un deployment slot de staging en Azure App Service antes de hacer swap a producción?","Permite validar la nueva versión en un entorno equivalente, con warm-up, antes de exponerla al tráfico real, reduciendo el riesgo y el downtime del despliegue","Elimina la necesidad de ejecutar pruebas automatizadas en el pipeline de CI","Duplica automáticamente el costo del App Service Plan sin beneficio","Solo sirve para almacenar backups de la base de datos",0,"El slot de staging permite probar la versión nueva con configuración realista y ya inicializada antes del swap, minimizando el impacto de un despliegue defectuoso en producción."),
  sqr("Si un swap a producción introduce un bug crítico detectado minutos después, ¿cuál es la acción de menor riesgo disponible en App Service?","Ejecutar un swap inverso para restaurar rápidamente la versión previa en producción","Eliminar el App Service Plan completo y recrearlo desde cero","Esperar el siguiente ciclo de CI/CD sin tomar ninguna acción inmediata","Modificar manualmente los binarios en producción vía FTP como primera respuesta",0,"El swap inverso es la vía rápida y de bajo riesgo para revertir, ya que la versión anterior sigue disponible en el otro slot inmediatamente después del intercambio."),
  sqr("¿Cuál es una consecuencia de escribir archivos de log únicamente dentro del sistema de archivos de un contenedor en producción?","Los logs se pierden si el contenedor se reemplaza o reinicia, ya que su sistema de archivos es efímero por defecto","Los logs quedan disponibles para siempre sin importar qué pase con el contenedor","Mejora automáticamente el rendimiento de la aplicación","Azure App Service prohíbe esta práctica y no arranca el contenedor",0,"Los contenedores son efímeros; sin un volumen persistente o un destino externo (stdout recolectado, sistema de logging centralizado), los logs locales desaparecen al destruirse el contenedor."),
  sqr("Trampa de entrevista integradora: ¿basta con tener EXPOSE en el Dockerfile y depends_on en Compose para garantizar que la API no reciba tráfico hasta que la base de datos esté realmente lista?","No; EXPOSE solo documenta el puerto y depends_on solo ordena el arranque, ninguno espera a que el servicio interno esté listo para conexiones; se necesitan healthchecks o reintentos en la app","Sí, esa combinación es suficiente y garantiza el orden de disponibilidad real","Sí, pero solo si se usa la etiqueta 'latest' en la imagen","No, porque depends_on detiene completamente el arranque de api hasta que db esté sana por defecto",0,"Ninguna de las dos instrucciones garantiza disponibilidad real del servicio interno; para eso se usan healthchecks en Compose (condition: service_healthy) o lógica de reintentos/health checks en la propia aplicación."),
 ]},
];

const stepsN10: AdvancedStep[] = [
 {id:"n10-webapplicationfactory",title:"WebApplicationFactory",summary:"WebApplicationFactory<TEntryPoint> (del paquete Microsoft.AspNetCore.Mvc.Testing) crea un servidor de pruebas en memoria que hospeda toda la aplicación ASP.NET Core real, incluyendo su pipeline de middleware y contenedor de DI, sin necesidad de un servidor Kestrel escuchando en un puerto de red real. Permite crear un HttpClient que envía solicitudes directamente al pipeline en memoria, ideal para pruebas de integración rápidas y realistas.",code:"public class OrdersApiTests : IClassFixture<WebApplicationFactory<Program>> {\n  private readonly HttpClient _client;\n  public OrdersApiTests(WebApplicationFactory<Program> factory) {\n    _client = factory.CreateClient();\n  }\n\n  [Fact]\n  public async Task Get_Orders_Returns200() {\n    var response = await _client.GetAsync(\"/api/orders\");\n    response.EnsureSuccessStatusCode();\n  }\n}",questions:[
  sqr("¿Qué provee `WebApplicationFactory<TEntryPoint>` en pruebas de integración de ASP.NET Core?","Un host de pruebas en memoria que ejecuta el pipeline real de la app (middleware, DI) sin abrir un puerto de red real","Una base de datos en memoria exclusivamente para Entity Framework","Un framework de mocking para reemplazar todos los servicios registrados","Un generador de datos de prueba aleatorios",0,"WebApplicationFactory arranca la aplicación en un TestServer in-memory, ejecutando el pipeline de middleware y el contenedor de DI reales, sin necesidad de Kestrel escuchando en un puerto de red."),
  sqr("¿Qué requisito debe cumplir la clase `Program` (o el tipo usado como TEntryPoint) para que `WebApplicationFactory<Program>` funcione con top-level statements?","Debe ser accesible desde el proyecto de pruebas; con top-level statements suele requerirse exponerla, típicamente agregando `public partial class Program { }` al final de Program.cs","No requiere nada especial, siempre es accesible automáticamente sin cambios","Debe implementar una interfaz IEntryPoint","Debe estar decorada con [TestEntryPoint]",1,"Con top-level statements, el compilador genera una clase Program interna por defecto; para poder referenciarla como tipo genérico desde el proyecto de pruebas se agrega una declaración parcial pública explícita."),
  sqr("¿Qué método de WebApplicationFactory se usa típicamente para obtener un HttpClient que envía solicitudes al servidor en memoria?","factory.CreateClient()","factory.GetHttpClient()","new HttpClient(factory)","factory.Build().Client",0,"CreateClient() configura un HttpClient conectado directamente al TestServer en memoria, incluyendo el BaseAddress simulado."),
  sqr("¿Por qué IClassFixture<WebApplicationFactory<Program>> es útil en xUnit para este tipo de pruebas?","Comparte una única instancia del host de pruebas entre todos los tests de la clase, evitando el costo de reconstruirlo en cada test","Obliga a xUnit a ejecutar los tests en paralelo forzosamente","Crea una nueva base de datos física antes de cada test individual","Es un requisito de C# para declarar clases de test",0,"IClassFixture<T> en xUnit comparte la instancia de la fixture (aquí, el WebApplicationFactory) entre los tests de la clase, reduciendo el overhead de arrancar el host repetidamente."),
  sqr("¿Qué método se sobrescribe comúnmente en una subclase de WebApplicationFactory para reemplazar servicios (por ejemplo, sustituir una base de datos real por una en memoria) antes de las pruebas?","ConfigureWebHost, usando builder.ConfigureServices para reemplazar registros de DI","OnStart, definido en Program.cs","ReplaceServices, un método estático de xUnit","ConfigureTestDb, un método obligatorio del framework",0,"ConfigureWebHost permite interceptar la configuración del host de pruebas y, dentro de ConfigureServices, remover y volver a registrar servicios (por ejemplo, sustituir el DbContext por una versión en memoria o de prueba)."),
  sqr("¿El uso de WebApplicationFactory implica que la app escuche en un puerto TCP real accesible desde otros procesos del sistema operativo?","No; el TestServer procesa las solicitudes en memoria dentro del mismo proceso de pruebas, sin abrir un puerto de red real por defecto","Sí, siempre abre un puerto real aleatorio que debe cerrarse manualmente","Sí, y ese puerto queda expuesto públicamente por defecto","No, pero requiere Docker para funcionar",0,"El TestServer intercepta las solicitudes HTTP directamente a nivel de pipeline en memoria, evitando la sobrecarga y complejidad de un socket de red real."),
  sqr("¿Qué ventaja tienen las pruebas con WebApplicationFactory frente a pruebas unitarias que mockean cada dependencia individualmente?","Verifican el comportamiento real de la app completa (routing, middleware, filtros, serialización) en vez de solo la lógica aislada de una clase","Son siempre más rápidas de ejecutar que cualquier prueba unitaria","Eliminan por completo la necesidad de pruebas unitarias","No requieren compilar el proyecto de la app",0,"Las pruebas de integración con WebApplicationFactory validan que las piezas reales trabajen juntas correctamente (routing, model binding, filtros, DI), algo que las pruebas unitarias aisladas no cubren."),
  sqr("¿Qué método se usa para cambiar la configuración del entorno (por ejemplo forzar 'Testing' como ASPNETCORE_ENVIRONMENT) al crear el WebApplicationFactory?","Sobrescribir UseEnvironment dentro de ConfigureWebHost de una subclase personalizada","Modificar appsettings.json en producción directamente","No es posible cambiar el entorno en pruebas","Usar únicamente variables de entorno del sistema operativo host obligatoriamente",0,"WebHostBuilder expone UseEnvironment, que puede invocarse dentro de ConfigureWebHost en una subclase de WebApplicationFactory para forzar un entorno específico de pruebas."),
  sqr("¿Qué ocurre si un test crea una nueva instancia de WebApplicationFactory en cada método de prueba en lugar de compartirla vía IClassFixture?","El host de pruebas se reconstruye por completo en cada test, aumentando el tiempo total de ejecución de la suite","Los tests fallan siempre por conflicto de puertos","Es la única forma válida de usar WebApplicationFactory","Mejora el aislamiento sin ningún costo de rendimiento",0,"Recrear el host en cada test es válido para mayor aislamiento, pero tiene un costo de rendimiento; compartir la instancia (IClassFixture) amortiza ese costo cuando el aislamiento total no es estrictamente necesario."),
  sqr("Trampa de entrevista: ¿WebApplicationFactory reemplaza por completo la necesidad de tener pruebas unitarias más granulares?","No; complementa a las pruebas unitarias, cubriendo el comportamiento end-to-end del pipeline HTTP, mientras que las unitarias siguen siendo útiles para lógica de negocio aislada y rápida de verificar","Sí, todas las pruebas deberían migrarse a WebApplicationFactory exclusivamente","No, WebApplicationFactory solo sirve para pruebas de UI","Sí, porque las pruebas unitarias no pueden coexistir con pruebas de integración en el mismo proyecto",0,"Ambos tipos de pruebas cumplen roles distintos y complementarios: unitarias para lógica aislada y rápida, de integración (con WebApplicationFactory) para validar el comportamiento real del sistema ensamblado."),
 ]},
 {id:"n10-integration-tests",title:"Integration tests",summary:"Las pruebas de integración verifican que varios componentes reales (controladores, DI, base de datos, middleware) funcionan correctamente juntos, a diferencia de las pruebas unitarias que aíslan una sola unidad de código reemplazando sus dependencias. Son más lentas y complejas de preparar que las unitarias, pero detectan problemas de integración que las pruebas unitarias, por diseño, no pueden ver.",code:"[Fact]\npublic async Task Post_Order_PersistsToDatabase() {\n  await using var app = new WebApplicationFactory<Program>()\n      .WithWebHostBuilder(builder => builder.ConfigureServices(services => {\n          services.RemoveAll<DbContextOptions<AppDbContext>>();\n          services.AddDbContext<AppDbContext>(o => o.UseInMemoryDatabase(\"tests\"));\n      }));\n  var client = app.CreateClient();\n\n  var response = await client.PostAsJsonAsync(\"/api/orders\", new { ProductId = 1, Quantity = 2 });\n\n  response.EnsureSuccessStatusCode();\n}",questions:[
  sqr("¿Cuál es la diferencia fundamental entre una prueba unitaria y una prueba de integración?","La unitaria aísla una unidad de código reemplazando sus dependencias; la de integración verifica que varios componentes reales colaboran correctamente","Son términos equivalentes usados indistintamente en la industria","La unitaria siempre requiere una base de datos real; la de integración nunca la usa","La de integración solo aplica a interfaces de usuario",0,"Las pruebas unitarias aíslan la unidad bajo prueba (mockeando dependencias); las de integración ejercitan la colaboración real entre varios componentes del sistema."),
  sqr("En el ejemplo, ¿qué logra `services.RemoveAll<DbContextOptions<AppDbContext>>()` seguido de `AddDbContext(...UseInMemoryDatabase...)`?","Reemplaza el registro original del DbContext (probablemente apuntando a SQL Server real) por uno que usa un proveedor en memoria, aislando el test de una base de datos externa","Elimina completamente la posibilidad de usar Entity Framework en el test","Borra todos los datos de la base de datos de producción","Convierte la prueba de integración en una prueba unitaria automáticamente",0,"RemoveAll quita el registro previo del DbContextOptions configurado en Program.cs para producción, y AddDbContext con UseInMemoryDatabase lo sustituye por un proveedor en memoria adecuado para pruebas rápidas y aisladas."),
  sqr("¿Por qué las pruebas de integración suelen ser más lentas que las unitarias?","Porque ejercitan más infraestructura real (pipeline HTTP, DI, a veces base de datos), lo que implica más trabajo por prueba que una unidad aislada","Porque siempre requieren conexión a internet","Porque xUnit ejecuta las pruebas de integración en un hilo distinto siempre","Porque las pruebas de integración no pueden usar async/await",0,"Al involucrar más piezas reales del sistema (en vez de dobles de prueba simples), cada prueba de integración tiene más trabajo real que ejecutar, incrementando el tiempo respecto a una prueba unitaria aislada."),
  sqr("¿Qué riesgo existe si TODAS las pruebas de un proyecto son de integración y ninguna es unitaria?","La suite de pruebas se vuelve lenta y frágil para verificar reglas de negocio puntuales, dificultando obtener feedback rápido durante el desarrollo","Ningún riesgo, las pruebas de integración cubren siempre exactamente lo mismo que las unitarias sin costo adicional","Las pruebas de integración no pueden fallar nunca por definición","Se pierde la capacidad de probar endpoints HTTP",0,"Depender solo de pruebas de integración hace la suite más lenta y compleja de mantener para casos de lógica pura, que las pruebas unitarias podrían validar de forma mucho más rápida y aislada."),
  sqr("En una 'pirámide de pruebas' tradicional, ¿qué proporción relativa suelen tener las pruebas de integración frente a las unitarias?","Menos pruebas de integración que unitarias, ya que las unitarias son más rápidas y baratas de mantener","Exactamente la misma cantidad en cualquier proyecto sano","Más pruebas de integración que unitarias siempre","Las pruebas unitarias no deberían existir si hay pruebas de integración",0,"La pirámide de pruebas sugiere una base amplia de pruebas unitarias rápidas, una capa intermedia más pequeña de pruebas de integración, y menos pruebas end-to-end en la cima, priorizando velocidad de feedback."),
  sqr("¿Qué método HTTP de HttpClient se usa en el ejemplo para enviar un objeto serializado como JSON en el cuerpo de la solicitud?","client.PostAsJsonAsync","client.GetAsJsonAsync","client.SendJson","client.PutFormAsync",0,"PostAsJsonAsync (de System.Net.Http.Json) serializa el objeto a JSON y lo envía en una solicitud POST, retornando un HttpResponseMessage."),
  sqr("¿Qué verifica `response.EnsureSuccessStatusCode()` en el test de integración?","Lanza una excepción si el código de estado HTTP no está en el rango de éxito (2xx), haciendo fallar el test en ese caso","Verifica que la respuesta contenga JSON válido únicamente","Reintenta automáticamente la solicitud si falla","Verifica que el tiempo de respuesta sea menor a un segundo",0,"EnsureSuccessStatusCode lanza HttpRequestException si el StatusCode no es exitoso (2xx), lo cual xUnit interpreta como una prueba fallida si no se maneja."),
  sqr("¿Qué ventaja tiene usar una base de datos en memoria (In-Memory Database provider de EF Core) en pruebas de integración frente a una base de datos real como SQL Server?","Es más rápida y no requiere infraestructura externa, aunque no reproduce con exactitud comportamientos específicos del motor real (como restricciones o funciones SQL propias)","Reproduce exactamente el comportamiento de SQL Server en todos los casos","Elimina la necesidad de escribir cualquier tipo de prueba adicional","Solo puede usarse en pruebas unitarias, nunca en pruebas de integración",0,"El proveedor en memoria de EF Core es rápido y conveniente, pero no es un motor relacional real: no valida restricciones SQL, tipos específicos ni comportamientos de concurrencia idénticos a un motor real como SQL Server."),
  sqr("¿Qué es una posible desventaja de usar un proveedor de base de datos en memoria en vez de Testcontainers con una base de datos real para pruebas de integración de persistencia?","Puede dar falsos positivos: la prueba pasa contra el proveedor en memoria pero falla contra el motor SQL real por diferencias de comportamiento","No tiene ninguna desventaja relevante en ningún escenario","Es siempre más lento que usar Testcontainers","No puede usarse junto con WebApplicationFactory",0,"El proveedor en memoria no implementa fielmente todas las características de un motor SQL real (constraints, tipos, transacciones, funciones), por lo que una prueba puede pasar ahí y fallar contra la base real."),
  sqr("Trampa de entrevista: ¿una prueba de integración que reemplaza la base de datos real por un proveedor en memoria deja de ser 'de integración' y pasa a ser 'unitaria'?","No necesariamente: sigue ejercitando la integración real de controladores, DI, middleware y serialización HTTP; solo se aisló la persistencia, un límite de test legítimo y común","Sí, cualquier reemplazo de una dependencia real convierte automáticamente la prueba en unitaria","No, porque las pruebas de integración nunca pueden reemplazar ninguna dependencia bajo ninguna circunstancia","Sí, porque WebApplicationFactory solo puede usarse en pruebas unitarias",0,"La clasificación depende de qué se integra realmente: aquí se sigue ejercitando el pipeline HTTP completo y el ensamblado de componentes, solo se sustituyó la base de datos por conveniencia y velocidad, lo cual sigue siendo una prueba de integración con un límite bien definido."),
 ]},
 {id:"n10-testcontainers",title:"Testcontainers",summary:"Testcontainers es una librería que levanta contenedores Docker reales y desechables (bases de datos, colas de mensajes, etc.) durante la ejecución de pruebas automatizadas, en vez de mockear esas dependencias o usar sustitutos en memoria. Esto da mayor fidelidad: las pruebas corren contra el motor real (por ejemplo PostgreSQL o SQL Server reales), detectando problemas que un proveedor en memoria no puede detectar, a cambio de pruebas algo más lentas y que requieren Docker disponible en el entorno de CI.",code:"var container = new MsSqlBuilder().Build();\nawait container.StartAsync();\n\nvar options = new DbContextOptionsBuilder<AppDbContext>()\n    .UseSqlServer(container.GetConnectionString())\n    .Options;\n\nawait using var db = new AppDbContext(options);\nawait db.Database.MigrateAsync();\n\n// ... ejecutar pruebas contra la base de datos real en el contenedor ...\n\nawait container.DisposeAsync();",questions:[
  sqr("¿Qué problema resuelve Testcontainers respecto a usar un proveedor de base de datos en memoria en pruebas de integración?","Ejecuta pruebas contra un motor de base de datos real dentro de un contenedor Docker desechable, evitando diferencias de comportamiento frente al proveedor en memoria","Elimina por completo la necesidad de tener Docker instalado en la máquina de CI","Convierte automáticamente cualquier prueba unitaria en prueba end-to-end","Reemplaza la necesidad de usar WebApplicationFactory en pruebas HTTP",0,"Testcontainers da mayor fidelidad al usar el motor de base de datos real (por ejemplo SQL Server o PostgreSQL) en un contenedor, capturando comportamientos (constraints, tipos, funciones SQL) que un proveedor en memoria no reproduce."),
  sqr("¿Qué requisito de infraestructura es indispensable para que Testcontainers funcione en un pipeline de CI?","Tener un motor Docker disponible y accesible en el runner de CI","Tener Kubernetes instalado en el runner","Una licencia comercial de Testcontainers obligatoria","Acceso a internet público sin restricciones de red",0,"Testcontainers necesita comunicarse con un daemon Docker para crear y destruir contenedores; sin Docker disponible en el runner, las pruebas no pueden ejecutarse."),
  sqr("En el ejemplo, ¿qué hace `container.GetConnectionString()` tras `StartAsync()`?","Devuelve la cadena de conexión válida para conectarse a la instancia de SQL Server que corre dentro del contenedor recién iniciado, incluyendo el puerto asignado dinámicamente","Devuelve la cadena de conexión de la base de datos de producción","Genera una cadena de conexión ficticia sin conexión real","Requiere pasar manualmente el puerto expuesto como parámetro obligatorio",0,"Testcontainers asigna puertos dinámicamente para evitar conflictos entre ejecuciones concurrentes, y GetConnectionString entrega una cadena ya lista con el host y puerto correctos del contenedor iniciado."),
  sqr("¿Por qué se llama `await db.Database.MigrateAsync()` después de crear el DbContext contra el contenedor de Testcontainers?","Porque el contenedor arranca con una base de datos vacía; hay que aplicar las migraciones de EF Core para crear el esquema antes de usarlo en las pruebas","Porque MigrateAsync es obligatorio incluso en producción antes de cualquier consulta","Porque Testcontainers no puede iniciar contenedores sin una migración previa","Porque MigrateAsync elimina datos de pruebas anteriores automáticamente por diseño",0,"Un contenedor de base de datos recién creado no tiene el esquema de la aplicación; aplicar las migraciones (o un script equivalente) es necesario para tener las tablas antes de ejercitar las pruebas."),
  sqr("¿Qué ventaja de fidelidad ofrece Testcontainers frente al proveedor EF Core InMemory al probar una restricción de unicidad definida a nivel de base de datos?","Testcontainers ejecuta contra un motor real que aplica esa restricción; el proveedor InMemory puede no simular fielmente restricciones específicas del motor SQL","Ambos simulan exactamente igual cualquier restricción de base de datos","El proveedor InMemory siempre es más estricto que un motor SQL real","Testcontainers no soporta restricciones de unicidad bajo ninguna circunstancia",0,"El proveedor InMemory de EF Core no implementa completamente el conjunto de validaciones/restricciones de un motor relacional real, mientras que Testcontainers corre contra el motor auténtico, detectando violaciones reales."),
  sqr("¿Qué costo tiene usar Testcontainers en comparación con un proveedor de base de datos en memoria, en términos de velocidad de la suite de pruebas?","Es más lento, porque implica iniciar y destruir contenedores Docker reales en cada ejecución (o grupo de ejecuciones)","Es siempre más rápido que cualquier proveedor en memoria","No tiene ningún costo adicional de tiempo","Solo afecta el tiempo de compilación, no el de ejecución de pruebas",0,"Levantar contenedores Docker reales añade overhead de arranque comparado con una estructura puramente en memoria, aunque a cambio se gana fidelidad frente al comportamiento real del motor."),
  sqr("¿Qué tipo de dependencias, además de bases de datos relacionales, pueden probarse con Testcontainers?","Otras dependencias con imagen Docker disponible, como colas de mensajes (RabbitMQ, Kafka), Redis o motores NoSQL","Únicamente bases de datos SQL Server","Solo servicios expuestos públicamente en internet","Solo dependencias que no requieran red",0,"Testcontainers soporta cualquier dependencia empaquetable en una imagen Docker, incluyendo colas de mensajes, cachés como Redis, motores NoSQL, y más, no solo bases de datos relacionales."),
  sqr("¿Por qué es importante destruir (dispose) los contenedores de Testcontainers al finalizar las pruebas, como en `await container.DisposeAsync()`?","Para liberar los recursos (contenedor, red, volumen) y evitar dejar contenedores huérfanos consumiendo recursos en la máquina de CI","Porque de lo contrario el pipeline de CI nunca finaliza su ejecución","Porque Docker elimina automáticamente todos los contenedores al finalizar cualquier proceso, haciendo el dispose innecesario","Porque sin dispose, las pruebas fallan siempre con un error de sintaxis",1,"No liberar contenedores puede acumular recursos huérfanos en el entorno de ejecución; DisposeAsync detiene y elimina el contenedor de prueba explícitamente, aunque muchas implementaciones también limpian automáticamente al finalizar el proceso."),
  sqr("¿Qué mecanismo usa Testcontainers para evitar conflictos de puertos cuando se ejecutan pruebas en paralelo en distintos contenedores del mismo tipo de base de datos?","Asigna puertos del host dinámicamente/aleatoriamente en vez de usar siempre el puerto fijo por defecto del servicio","Obliga a ejecutar las pruebas de forma estrictamente secuencial en toda la organización","Reutiliza siempre el mismo contenedor entre ejecuciones paralelas distintas","Requiere configurar manualmente un puerto único por cada desarrollador",0,"Al mapear el puerto del contenedor a un puerto aleatorio disponible del host, Testcontainers permite ejecutar múltiples instancias en paralelo sin colisiones de puerto."),
  sqr("Trampa de entrevista: ¿Testcontainers reemplaza la necesidad de tener un entorno de staging separado antes de producción?","No; Testcontainers mejora la fidelidad de las pruebas automatizadas de integración, pero no sustituye la validación en un entorno de staging con configuración más cercana a producción","Sí, Testcontainers hace innecesario cualquier entorno adicional de pruebas manuales","Sí, porque los contenedores de Testcontainers son idénticos a producción en todos los aspectos, incluida infraestructura de red","No, porque Testcontainers no puede ejecutarse en pipelines de CI",0,"Testcontainers mejora la confiabilidad de las pruebas automatizadas al usar dependencias reales, pero sigue siendo parte de la suite de pruebas; un entorno de staging cumple un propósito distinto y complementario de validación previa a producción."),
 ]},
 {id:"n10-mocks-fakes",title:"Mocks vs fakes",summary:"Un mock es un doble de prueba que registra y permite verificar interacciones (qué métodos se llamaron, con qué argumentos, cuántas veces), típicamente creado con librerías como Moq o NSubstitute. Un fake es una implementación funcional simplificada de una dependencia (por ejemplo, un repositorio respaldado por una lista en memoria en vez de una base de datos). Un stub, distinto de ambos, simplemente devuelve respuestas predefinidas sin verificar interacciones ni implementar lógica real.",code:"// Mock con Moq: verifica una interacción\nvar emailServiceMock = new Mock<IEmailService>();\nvar handler = new OrderHandler(emailServiceMock.Object);\n\nhandler.Complete(new Order { Id = 1 });\n\nemailServiceMock.Verify(s => s.SendConfirmation(1), Times.Once);\n\n// Fake: implementación funcional simplificada\npublic class FakeOrderRepository : IOrderRepository {\n  private readonly List<Order> _orders = new();\n  public void Add(Order order) => _orders.Add(order);\n  public Order? Find(int id) => _orders.FirstOrDefault(o => o.Id == id);\n}",questions:[
  sqr("¿Cuál es la diferencia esencial entre un mock y un fake como dobles de prueba?","Un mock verifica que ciertas interacciones (llamadas a métodos) ocurrieron; un fake es una implementación funcional simplificada que realmente se comporta como la dependencia real","Son términos intercambiables sin diferencia práctica","Un fake siempre requiere una librería como Moq; un mock nunca la requiere","Un mock solo puede usarse con bases de datos reales",0,"Un mock se centra en verificar interacciones (qué se llamó y cómo); un fake tiene lógica funcional real, aunque simplificada, como una lista en memoria actuando como repositorio."),
  sqr("En el ejemplo, ¿qué verifica `emailServiceMock.Verify(s => s.SendConfirmation(1), Times.Once)`?","Que el método SendConfirmation(1) se haya invocado exactamente una vez sobre el mock durante la ejecución del test","Que el correo realmente fue entregado al destinatario","Que SendConfirmation nunca se llamó bajo ninguna circunstancia","Que el mock lanzó una excepción durante la ejecución",0,"Verify comprueba una expectativa sobre las interacciones registradas por el mock, aquí que SendConfirmation(1) se llamó una única vez, sin implicar que un correo real se haya enviado."),
  sqr("¿Qué caracteriza específicamente a un stub, a diferencia de un mock?","Un stub devuelve respuestas predefinidas cuando se le invoca, sin implementar lógica de negocio real ni enfocarse en verificar interacciones como hace un mock","Un stub siempre requiere conexión a una base de datos real","Un stub es sinónimo exacto de mock en la literatura de pruebas","Un stub solo puede devolver null",0,"Un stub simplemente retorna valores fijos o predefinidos ante ciertas llamadas; a diferencia del mock, el foco no está en verificar que se llamó, sino en simplemente proveer una respuesta controlada."),
  sqr("¿Por qué `FakeOrderRepository` en el ejemplo se considera un fake y no un mock?","Porque implementa realmente la lógica de un repositorio (agregar y buscar) usando una estructura en memoria, no solo registra llamadas para verificarlas después","Porque usa la librería Moq internamente","Porque siempre lanza excepciones al ser invocado","Porque no implementa la interfaz IOrderRepository",0,"FakeOrderRepository tiene comportamiento funcional real (una lista que almacena y busca), característica definitoria de un fake, a diferencia de un mock centrado en verificación de interacciones."),
  sqr("¿Cuándo conviene preferir un mock sobre un fake en una prueba unitaria?","Cuando lo importante es verificar que cierta interacción con una dependencia ocurrió (por ejemplo, que se envió una notificación), más que el estado resultante","Siempre, un mock es preferible en absolutamente todos los escenarios de prueba","Nunca, los fakes deben usarse exclusivamente en cualquier escenario","Solo cuando la dependencia no tiene una interfaz definida",0,"Los mocks son ideales cuando el comportamiento a validar es 'se debió llamar a X con estos argumentos', un caso de verificación de interacción, no de estado resultante."),
  sqr("¿Qué riesgo tiene sobreusar mocks para verificar detalles de implementación internos de una clase, en vez de su comportamiento observable?","Los tests se vuelven frágiles: cualquier refactorización interna (aunque el comportamiento externo no cambie) puede romper pruebas que verifican llamadas específicas","Ningún riesgo, verificar implementación interna siempre es preferible al comportamiento externo","Los mocks eliminan automáticamente la necesidad de refactorizar código","Sobreusar mocks mejora automáticamente la cobertura de código sin ningún costo",0,"Verificar demasiados detalles de 'cómo' se logra un resultado (en vez de 'qué' resultado se logra) acopla las pruebas a la implementación, haciéndolas frágiles ante refactorizaciones legítimas que no cambian el comportamiento externo."),
  sqr("¿Qué ventaja tiene usar un fake sobre un mock cuando se prueba lógica que depende de múltiples operaciones secuenciales sobre un repositorio (agregar y luego buscar)?","El fake mantiene un estado real y consistente entre llamadas (por ejemplo, lo agregado con Add aparece luego en Find), algo que configurar con un mock puro sería más artificioso","El mock siempre mantiene estado real automáticamente entre llamadas","No hay ninguna diferencia práctica entre ambos enfoques en este escenario","Los fakes no pueden implementar interfaces con más de un método",0,"Al tener lógica funcional real, un fake refleja naturalmente el efecto de operaciones secuenciales (agregar y luego encontrar), mientras que un mock configurado con valores fijos requeriría más configuración artificial para simular ese estado."),
  sqr("¿Qué librería es una opción común en .NET para crear mocks de interfaces en pruebas unitarias, además de Moq?","NSubstitute","Entity Framework Core","AutoMapper","Serilog",0,"NSubstitute es otra librería popular de mocking en .NET, alternativa a Moq, con una sintaxis distinta pero un propósito equivalente."),
  sqr("¿Por qué es importante que las dependencias que se van a mockear o fakear estén expresadas como interfaces (o clases con miembros virtuales) en el código de producción?","Porque los frameworks de mocking (como Moq) generalmente necesitan un contrato sustituible (interfaz o miembro virtual) para crear una implementación de prueba dinámicamente","Porque C# no permite instanciar clases concretas en pruebas bajo ninguna circunstancia","Porque las interfaces mejoran automáticamente el rendimiento de las pruebas","Porque los fakes solo pueden implementarse dentro de la misma clase que los usa",0,"Herramientas como Moq generan implementaciones dinámicas de una interfaz (o sobrescriben miembros virtuales); sin ese punto de sustitución, no es posible interceptar ni reemplazar el comportamiento fácilmente."),
  sqr("Trampa de entrevista: ¿es correcto decir que 'mock' es el término genérico correcto para referirse a cualquier doble de prueba, incluyendo fakes y stubs?","No es preciso: 'test double' es el término genérico; mock, fake y stub son categorías específicas con propósitos distintos dentro de esa familia","Sí, mock es sinónimo perfecto y técnico de cualquier doble de prueba","No, porque solo existen mocks y fakes, los stubs no son un concepto real","Sí, pero solo en el contexto específico de .NET",0,"En la terminología de pruebas (popularizada por Gerard Meszaros), 'test double' es el paraguas general; mock, fake, stub, dummy y spy son tipos específicos con comportamientos y propósitos distintos, y usarlos como sinónimos es impreciso."),
 ]},
 {id:"n10-contract-tests",title:"Contract tests",summary:"Los contract tests (pruebas de contrato) verifican que un consumidor (por ejemplo un frontend o un microservicio cliente) y un proveedor (una API) cumplen un acuerdo compartido sobre la forma de las solicitudes y respuestas, sin necesidad de desplegar ambos servicios juntos en cada prueba. Herramientas como Pact generan un 'contrato' desde las expectativas del consumidor y lo verifican automáticamente contra el proveedor real, detectando cambios que rompen la integración antes de llegar a producción.",code:"// Lado consumidor (genera el contrato/pact)\nvar pact = Pact.V3(\"OrdersUI\", \"OrdersApi\", new PactConfig());\npact.UponReceiving(\"una solicitud de orden existente\")\n    .Given(\"la orden 1 existe\")\n    .WithRequest(HttpMethod.Get, \"/api/orders/1\")\n    .WillRespond()\n    .WithStatus(200)\n    .WithJsonBody(new { id = 1, total = 99.90 });\n\n// Lado proveedor: se verifica que la API real cumple ese contrato publicado",questions:[
  sqr("¿Qué problema resuelven principalmente los contract tests entre un servicio consumidor y un servicio proveedor?","Detectar de forma temprana y automatizada si un cambio en el proveedor rompe el contrato esperado por el consumidor, sin necesidad de desplegar ambos servicios integrados en cada verificación","Reemplazar por completo la necesidad de pruebas end-to-end en cualquier escenario","Medir el rendimiento de la API bajo carga","Generar documentación visual de la interfaz de usuario",0,"Los contract tests permiten verificar la compatibilidad entre consumidor y proveedor de forma aislada y automatizada, detectando rupturas de contrato antes de una integración real costosa."),
  sqr("En un flujo típico con Pact, ¿quién define inicialmente las expectativas que se convierten en el contrato ('pact')?","El consumidor, describiendo las solicitudes que hará y las respuestas que espera recibir","El proveedor, sin ninguna intervención del consumidor","Un tercero externo ajeno a ambos equipos","El equipo de infraestructura de CI/CD exclusivamente",0,"En el enfoque 'consumer-driven contracts' que sigue Pact, el consumidor define sus expectativas de interacción, que luego se verifican automáticamente contra el proveedor real."),
  sqr("¿Qué significa que un contract test sea 'verificado contra el proveedor real' en Pact?","El proveedor ejecuta las interacciones descritas en el contrato contra su implementación real y confirma que las respuestas coinciden con lo esperado por el consumidor","El proveedor solo revisa el contrato manualmente sin ejecutar código","El consumidor despliega una copia completa del proveedor en su propio pipeline","El contrato se valida únicamente mediante inspección visual de un documento PDF",0,"La verificación del lado proveedor ejecuta las peticiones definidas en el pact contra el servicio real, comprobando que las respuestas cumplen lo pactado con el consumidor."),
  sqr("¿Qué ventaja tienen los contract tests frente a levantar un entorno end-to-end completo con todos los microservicios reales para cada verificación de integración?","Son más rápidos y aislados: cada lado (consumidor/proveedor) se verifica independientemente contra el contrato, sin depender de que todo el ecosistema esté desplegado simultáneamente","Los contract tests son siempre exactamente igual de lentos que un entorno end-to-end completo","Eliminan por completo la necesidad de desplegar el proveedor alguna vez","Solo funcionan si consumidor y proveedor están escritos en el mismo lenguaje de programación",0,"Al verificar cada lado contra un contrato compartido de forma independiente, se evita el costo y la fragilidad de mantener un entorno end-to-end completo desplegado para cada prueba de integración entre servicios."),
  sqr("¿Qué ocurre si el proveedor cambia la forma de su respuesta (por ejemplo, renombra un campo JSON) sin que el consumidor lo sepa, en un flujo con contract testing bien implementado?","La verificación del contrato en el pipeline del proveedor falla, alertando el cambio incompatible antes de desplegarlo a producción","Nada, los contract tests no pueden detectar cambios en el formato de la respuesta","El consumidor se actualiza automáticamente sin intervención humana","Solo se detecta el problema cuando un usuario final reporta un error en producción",0,"El objetivo central de los contract tests es justamente detectar este tipo de rupturas de compatibilidad antes del despliegue, verificando el proveedor contra las expectativas capturadas del consumidor."),
  sqr("¿Qué es un 'broker' de contratos (como Pact Broker) en un flujo de contract testing?","Un servicio centralizado donde se publican y consultan las versiones de los contratos entre consumidores y proveedores, coordinando qué versiones son compatibles","Un servidor de bases de datos exclusivo para pruebas de integración","Un componente que reemplaza la necesidad de escribir cualquier contrato","Un proxy que oculta errores de red durante las pruebas",0,"El Pact Broker almacena y versiona los contratos, permitiendo consultar la matriz de compatibilidad entre versiones de consumidores y proveedores antes de desplegar cambios."),
  sqr("¿Los contract tests reemplazan la necesidad de pruebas de integración o end-to-end dentro de un mismo servicio?","No; son complementarios: los contract tests se enfocan en la compatibilidad entre servicios distintos, mientras que las pruebas de integración/end-to-end siguen siendo útiles para validar el comportamiento interno de cada servicio","Sí, los contract tests cubren absolutamente todos los escenarios de prueba necesarios","Sí, porque contract testing y pruebas end-to-end son términos sinónimos","No, porque los contract tests solo aplican a pruebas unitarias de una sola clase",0,"Contract testing resuelve específicamente el problema de compatibilidad entre servicios que evolucionan por separado; no sustituye otras capas de prueba dentro del propio servicio."),
  sqr("¿En qué escenario de arquitectura los contract tests aportan más valor?","En arquitecturas de microservicios donde distintos equipos despliegan servicios de forma independiente y necesitan confianza sobre la compatibilidad de sus integraciones","En una aplicación monolítica de un solo proceso sin ninguna API externa","En scripts de un solo uso sin ningún consumidor externo","En pruebas de UI que no involucran ninguna llamada de red",0,"El valor de contract testing crece con la cantidad de servicios independientes que deben mantenerse compatibles entre sí sin coordinar despliegues simultáneos manualmente."),
  sqr("¿Qué diferencia hay entre un contract test y una prueba end-to-end tradicional que llama a la API real desplegada?","El contract test no requiere que ambos servicios estén desplegados y ejecutándose simultáneamente; verifica cada lado contra un contrato compartido de forma independiente","Son técnicamente idénticos y usan exactamente la misma infraestructura","El contract test siempre requiere una base de datos de producción real","La prueba end-to-end nunca puede fallar por problemas de red",0,"Las pruebas end-to-end requieren el sistema completo desplegado e interactuando en tiempo real; los contract tests desacoplan la verificación de cada lado usando el contrato como intermediario, sin necesitar ambos servicios activos simultáneamente."),
  sqr("Trampa de entrevista: ¿basta con que las pruebas unitarias del proveedor pasen para garantizar que no rompió la integración con sus consumidores reales?","No necesariamente; las pruebas unitarias validan la lógica interna del proveedor, pero no garantizan que el contrato de comunicación esperado por consumidores externos se mantenga intacto, que es justamente lo que valida el contract testing","Sí, las pruebas unitarias siempre garantizan la compatibilidad completa con cualquier consumidor externo","Sí, porque las pruebas unitarias y los contract tests verifican exactamente lo mismo","No, porque las pruebas unitarias nunca pueden pasar si hay un consumidor externo involucrado",0,"Las pruebas unitarias del proveedor pueden pasar perfectamente mientras el contrato con un consumidor específico se rompe (por ejemplo, un campo renombrado); el contract testing cierra específicamente ese vacío."),
 ]},
 {id:"n10-quality-pipeline",title:"Pipeline de calidad",summary:"Un pipeline de calidad para una app web integra varias capas automatizadas: pruebas unitarias rápidas, pruebas de integración (posiblemente con Testcontainers), análisis estático de código, medición de cobertura con un umbral mínimo, y opcionalmente contract tests o escaneo de vulnerabilidades de dependencias. El objetivo es dar retroalimentación confiable antes de fusionar cambios o desplegar, actuando como una red de seguridad automatizada y repetible.",code:"# Etapas típicas de un pipeline de calidad para web\nsteps:\n  - run: dotnet test --filter Category=Unit --collect:\"XPlat Code Coverage\"\n  - run: reportgenerator -reports:coverage.cobertura.xml -targetdir:coverage -reporttypes:TextSummary\n  - run: dotnet test --filter Category=Integration\n  - run: dotnet list package --vulnerable\n  - run: dotnet format --verify-no-changes",questions:[
  sqr("¿Por qué conviene separar la ejecución de pruebas unitarias y de integración en etapas distintas dentro del pipeline (como en el ejemplo con `--filter Category=Unit` y `Category=Integration`)?","Para obtener feedback rápido de las pruebas unitarias primero, y solo invertir el tiempo mayor de las pruebas de integración si las unitarias ya pasaron","Porque dotnet test no puede ejecutar ambos tipos de pruebas en la misma invocación bajo ninguna circunstancia","Porque las pruebas de integración no pueden usar la palabra clave Category","Porque separar las categorías es un requisito obligatorio de xUnit",0,"Ejecutar primero las pruebas unitarias (rápidas) permite fallar rápido ante errores de lógica simples, antes de invertir el tiempo más costoso de las pruebas de integración."),
  sqr("¿Qué mide la 'cobertura de código' (code coverage) reportada por herramientas como Coverlet/reportgenerator?","El porcentaje de líneas (o ramas) del código fuente que fueron ejecutadas al menos una vez durante la ejecución de las pruebas","La cantidad de bugs presentes en el código de forma exacta","La velocidad de ejecución de la suite de pruebas","El número total de líneas de código del proyecto",0,"La cobertura indica qué proporción del código fue efectivamente ejercitada por las pruebas, aunque un alto porcentaje no garantiza por sí solo ausencia de bugs ni buena calidad de aserciones."),
  sqr("¿Por qué una cobertura de código del 100% no garantiza la ausencia de bugs en la aplicación?","Porque la cobertura solo indica que el código se ejecutó, no que las aserciones verifiquen correctamente todos los comportamientos y casos límite relevantes","Porque 100% de cobertura es matemáticamente imposible de alcanzar en cualquier proyecto","Porque la cobertura mide únicamente el rendimiento de la aplicación","Porque las herramientas de cobertura siempre sobreestiman el porcentaje real",0,"Una línea puede ejecutarse sin que la prueba verifique realmente su comportamiento correcto (una prueba sin aserciones útiles); cobertura mide ejecución, no corrección."),
  sqr("¿Qué propósito tiene el comando `dotnet list package --vulnerable` en un pipeline de calidad?","Detectar dependencias NuGet con vulnerabilidades de seguridad conocidas antes de publicar o desplegar la aplicación","Actualizar automáticamente todas las dependencias a la última versión disponible","Eliminar paquetes NuGet no utilizados del proyecto","Compilar el proyecto en modo Release",0,"Este comando reporta paquetes referenciados que tienen vulnerabilidades conocidas registradas, permitiendo actuar (actualizar o mitigar) antes de que lleguen a producción."),
  sqr("¿Qué hace `dotnet format --verify-no-changes` en un pipeline, y por qué es útil como quality gate?","Verifica que el código ya está formateado según las reglas del proyecto, fallando el pipeline si formatear produciría cambios, forzando consistencia de estilo","Aplica formateo automáticamente y hace commit de los cambios sin intervención","Ejecuta las pruebas unitarias con un formato de salida distinto","Compila el proyecto usando una configuración de formato binaria",0,"Con --verify-no-changes, el comando no modifica archivos: solo falla si detecta que el código no cumple el formato esperado, sirviendo como control automatizado de estilo consistente."),
  sqr("¿Qué significa que una 'quality gate' de cobertura mínima (por ejemplo 80%) bloquee un pull request?","El pipeline falla y no permite fusionar el cambio si la cobertura de código calculada cae por debajo del umbral configurado","La cobertura mínima se ajusta automáticamente al valor actual de cada PR sin ningún umbral fijo","Bloquea únicamente el despliegue a producción, nunca la fusión del PR","No tiene ningún efecto real sobre el flujo de trabajo del equipo",0,"Una quality gate de cobertura establece un umbral automatizado; si el PR reduce la cobertura por debajo de ese umbral, el pipeline falla y típicamente impide la fusión hasta corregirlo."),
  sqr("¿Qué ventaja aporta ejecutar análisis estático de código (linters, analizadores Roslyn) como parte del pipeline de calidad, además de las pruebas automatizadas?","Detecta patrones problemáticos, código muerto o violaciones de estilo/reglas sin necesidad de ejecutar el programa, complementando lo que las pruebas dinámicas no cubren","Reemplaza completamente la necesidad de cualquier prueba unitaria o de integración","Solo sirve para medir el rendimiento en tiempo de ejecución","Analiza exclusivamente la ortografía de los comentarios del código",0,"El análisis estático inspecciona el código sin ejecutarlo, detectando problemas estructurales, de estilo o antipatrones que las pruebas dinámicas (que verifican comportamiento) no necesariamente detectan."),
  sqr("¿Por qué conviene que un pipeline de calidad se ejecute en cada pull request, y no solo periódicamente (por ejemplo una vez por semana)?","Para detectar y corregir problemas cerca del momento en que se introdujeron, cuando el contexto del cambio sigue fresco y el costo de corrección es menor","Ejecutar el pipeline con frecuencia siempre degrada la calidad del código","Los pipelines periódicos son más precisos que los pipelines por PR","No hay ninguna diferencia práctica entre ambas frecuencias",0,"Cuanto antes se detecta un problema respecto al momento en que se introdujo, más barato y sencillo resulta corregirlo; ejecutar el pipeline en cada PR maximiza esa cercanía temporal."),
  sqr("¿Qué riesgo corre un equipo que baja repetidamente el umbral de una quality gate cada vez que un PR no lo alcanza, en vez de mejorar las pruebas?","La quality gate deja de cumplir su función real de control de calidad, degradándose progresivamente hasta volverse ineficaz","Ningún riesgo, bajar el umbral siempre es una decisión técnica neutral","El pipeline se vuelve automáticamente más rápido sin ninguna desventaja","Mejora automáticamente la cobertura real del proyecto",0,"Ajustar el umbral hacia abajo en vez de mejorar las pruebas socava el propósito de la quality gate, permitiendo que la calidad real del código se degrade progresivamente sin que el pipeline lo refleje."),
  sqr("Trampa de entrevista: ¿un pipeline de calidad que solo ejecuta pruebas unitarias, sin pruebas de integración ni análisis estático, es suficiente para tener confianza real antes de desplegar una aplicación web completa?","No necesariamente; las pruebas unitarias no cubren integración real entre componentes, configuración, ni ciertos problemas estructurales que el análisis estático o las pruebas de integración sí detectan","Sí, las pruebas unitarias siempre son suficientes para cualquier tipo de aplicación","Sí, porque las pruebas unitarias automáticamente incluyen validación de integración","No, porque las pruebas unitarias nunca aportan ningún valor real",0,"Cada capa del pipeline de calidad cubre un tipo distinto de riesgo; limitarse solo a pruebas unitarias deja huecos importantes (integración real, estilo/antipatrones, vulnerabilidades) sin cubrir."),
 ]},
 {id:"n10-challenge",title:"Reto de testing web",summary:"Reto integrador del módulo: combina WebApplicationFactory para pruebas de integración en memoria, Testcontainers para fidelidad contra un motor de base de datos real, la distinción entre mocks/fakes/stubs, contract tests entre servicios, y un pipeline de calidad con etapas de pruebas, cobertura y análisis estático.",code:"// Flujo integrador de testing web\n// 1) Unit tests rápidos (mocks/fakes según el caso)\n// 2) Integration tests con WebApplicationFactory (+ InMemory DB si aplica)\n// 3) Integration tests de persistencia con Testcontainers (motor real)\n// 4) Contract tests entre consumidor y proveedor (Pact)\n// 5) Pipeline: unit -> coverage -> integration -> vulnerabilities -> format",questions:[
  sqr("¿Qué diferencia hay entre usar WebApplicationFactory con un proveedor InMemory de EF Core y usar Testcontainers con SQL Server real en pruebas de integración?","WebApplicationFactory + InMemory es más rápido pero menos fiel a comportamientos reales del motor SQL; Testcontainers ejecuta contra el motor real, con mayor fidelidad a costa de más tiempo","Son exactamente equivalentes en fidelidad y velocidad","Testcontainers no puede combinarse con WebApplicationFactory bajo ninguna circunstancia","InMemory siempre detecta más errores que Testcontainers",0,"Cada enfoque resuelve un trade-off distinto entre velocidad y fidelidad; combinarlos según el escenario (rápido para lógica general, real para casos sensibles a comportamiento SQL específico) es una estrategia común."),
  sqr("En una prueba unitaria de un OrderHandler que debe enviar una notificación al completar una orden, ¿qué doble de prueba es más apropiado para verificar 'se llamó a SendConfirmation exactamente una vez'?","Un mock, porque el foco está en verificar la interacción, no en simular un comportamiento funcional real de envío de correos","Un fake, porque los fakes siempre son mejores que los mocks en cualquier escenario","Un stub, porque los stubs verifican automáticamente cuántas veces se llamaron sus métodos","Ninguno; hay que usar siempre el servicio real de envío de correos en pruebas unitarias",0,"Verificar que ocurrió una interacción específica (llamada con ciertos argumentos, cierta cantidad de veces) es el propósito central de un mock, a diferencia de un fake (comportamiento funcional) o un stub (respuestas fijas)."),
  sqr("¿Por qué contract tests entre un frontend consumidor y una API proveedora son útiles incluso si ambos ya tienen pruebas de integración internas robustas?","Porque las pruebas de integración internas no garantizan que el formato de comunicación acordado entre ambos servicios se mantenga compatible tras cambios independientes en cada lado","Porque las pruebas de integración internas siempre son inútiles si existen contract tests","Porque los contract tests reemplazan completamente las pruebas de integración internas","Porque sin contract tests es imposible desplegar cualquier microservicio",0,"Las pruebas internas de cada servicio no verifican el contrato compartido entre ambos; contract testing llena específicamente ese vacío de compatibilidad entre servicios que evolucionan de forma independiente."),
  sqr("En el pipeline de calidad del ejemplo, ¿por qué las pruebas unitarias se ejecutan antes que las de integración?","Para obtener feedback rápido y barato primero, evitando gastar tiempo en pruebas de integración más costosas si ya hay errores detectables por pruebas unitarias","Porque dotnet test ordena las pruebas alfabéticamente sin posibilidad de configurarlo","Porque las pruebas de integración no pueden ejecutarse nunca después de las unitarias","Porque las categorías Unit e Integration deben tener el mismo nombre de clase",0,"Priorizar las pruebas rápidas y baratas (unitarias) permite fallar rápido antes de invertir el tiempo mayor que implican las pruebas de integración."),
  sqr("¿Qué mide realmente la cobertura de código reportada en el pipeline, y qué limitación importante tiene como métrica de calidad?","Mide qué porcentaje del código se ejecutó durante las pruebas; no garantiza que las aserciones verifiquen correctamente el comportamiento esperado en cada caso","Mide directamente el número de bugs presentes en producción","Mide el tiempo de respuesta promedio de los endpoints probados","Mide la cantidad de commits realizados durante el sprint",0,"La cobertura es una métrica de ejecución, no de corrección; código cubierto por pruebas sin aserciones significativas puede tener 100% de cobertura y aun así ocultar bugs."),
  sqr("¿Qué implica que WebApplicationFactory ejecute las solicitudes contra un TestServer en memoria en vez de un servidor Kestrel real escuchando en un puerto?","Las pruebas son más rápidas al evitar el overhead de red real, mientras siguen ejercitando el pipeline HTTP real de la aplicación (middleware, routing, DI)","Las pruebas dejan de ser válidas como pruebas de integración por no usar red real","Es obligatorio configurar manualmente un puerto TCP libre antes de cada test","El TestServer no puede procesar solicitudes HTTP con cuerpo JSON",0,"El TestServer en memoria evita el costo de un socket de red real, pero mantiene la ejecución auténtica del pipeline de la aplicación, siendo una forma eficiente de prueba de integración."),
  sqr("¿Por qué `dotnet list package --vulnerable` es una etapa razonable dentro de un pipeline de calidad de una app web con muchas dependencias NuGet?","Detecta dependencias con vulnerabilidades conocidas antes de que lleguen a producción, un riesgo de seguridad frecuente en aplicaciones con muchas librerías de terceros","Porque reemplaza la necesidad de ejecutar cualquier prueba de seguridad manual","Porque actualiza automáticamente las dependencias vulnerables sin intervención","Porque mide el rendimiento de las dependencias en tiempo de ejecución",0,"Las dependencias de terceros son una superficie de riesgo habitual; escanear vulnerabilidades conocidas antes del despliegue es una práctica de seguridad básica dentro de un pipeline de calidad."),
  sqr("¿Qué riesgo de fidelidad existe si un equipo prueba toda su lógica de persistencia únicamente con el proveedor InMemory de EF Core, sin nunca usar Testcontainers ni una base real?","Podrían pasar pruebas que en realidad fallarían contra el motor SQL real por diferencias en restricciones, tipos o comportamiento de consultas","Ninguno, el proveedor InMemory es funcionalmente idéntico a cualquier motor SQL real","El proveedor InMemory es más lento que Testcontainers en todos los casos","EF Core no permite usar el proveedor InMemory en pruebas automatizadas",0,"El proveedor InMemory no reproduce fielmente el comportamiento de un motor relacional real; confiar solo en él para lógica sensible a ese comportamiento (constraints, tipos, SQL específico) puede dar una falsa sensación de seguridad."),
  sqr("¿Qué combinación de dobles de prueba sería más apropiada al probar un OrderHandler que depende de IEmailService (para verificar que se llamó) y de IOrderRepository (para verificar el estado tras Add/Find)?","Un mock para IEmailService (verificar interacción) y un fake para IOrderRepository (verificar estado tras operaciones secuenciales)","Un mock para ambas dependencias sin excepción","Un fake para ambas dependencias sin excepción","Ningún doble de prueba; siempre usar las implementaciones reales en pruebas unitarias",0,"El mock es adecuado cuando lo relevante es la interacción (se llamó SendConfirmation); el fake es más natural cuando se necesita reflejar estado real entre múltiples operaciones sobre el repositorio."),
  sqr("Trampa de entrevista integradora: ¿pasar el pipeline de calidad completo (unit, integration, cobertura, análisis estático) garantiza que no habrá ningún bug en producción?","No; el pipeline reduce significativamente el riesgo detectando muchas clases de problemas temprano, pero ninguna combinación de pruebas automatizadas garantiza ausencia total de bugs en producción","Sí, un pipeline de calidad completo elimina matemáticamente cualquier posibilidad de bug","Sí, siempre que la cobertura reportada sea del 100%","No, porque los pipelines de calidad nunca detectan ningún tipo de error real",0,"Ninguna suite de pruebas automatizadas, por completa que sea, puede garantizar ausencia total de bugs; reduce el riesgo y detecta muchas clases de problemas, pero no ofrece una garantía absoluta."),
 ]},
];

const stepsN11: AdvancedStep[] = [
 {id:"n11-csharp-fundamentals",title:"C# fundamentals",summary:"Preguntas de entrevista sobre fundamentos de C#: value types vs reference types, boxing/unboxing, semántica de igualdad, structs vs classes, y trampas comunes de tipado que se repiten en entrevistas técnicas reales.",code:"struct Point { public int X, Y; }\nint a = 5;\nobject boxed = a; // boxing\nint b = (int)boxed; // unboxing\n\nPoint p1 = new Point { X = 1, Y = 2 };\nPoint p2 = p1; // copia por valor\np2.X = 99;\nConsole.WriteLine(p1.X); // ?",questions:[
  sqr("¿Qué imprime `Console.WriteLine(p1.X)` en el código de ejemplo, tras modificar p2.X?","1, porque Point es un struct (value type) y p2 = p1 copió los valores, no una referencia compartida","99, porque p1 y p2 apuntan al mismo objeto","0, porque los structs no se pueden copiar con =","Error de compilación: los structs no permiten asignación",0,"Point es un struct; al asignar p2 = p1 se copian los campos por valor. Modificar p2.X no afecta a p1.X, a diferencia de lo que ocurriría con una clase."),
  sqr("¿Qué ocurre exactamente en la línea `object boxed = a;` cuando a es un int?","Se produce boxing: el valor de a se envuelve en un objeto en el heap para poder tratarlo como object","Se produce unboxing porque a pasa a ser un object","No ocurre ninguna conversión, int ya es un object internamente sin costo","Provoca un error de compilación porque int no es convertible a object",0,"Boxing convierte un value type en una instancia de referencia en el heap para que pueda usarse donde se espera un object o una interfaz; tiene un costo de asignación en el heap."),
  sqr("¿Qué trampa de rendimiento clásica de entrevista involucra boxing repetido dentro de un bucle que agrega enteros a una `ArrayList` (no genérica)?","Cada Add hace boxing del int a object, generando asignaciones en el heap y presión sobre el garbage collector en cada iteración","No hay ningún costo adicional, ArrayList maneja value types sin boxing","El boxing solo ocurre una vez sin importar cuántos elementos se agreguen","ArrayList convierte automáticamente los int en List<int> internamente",0,"ArrayList almacena object, así que cada value type agregado sufre boxing; usar List<int> (genérico) evita ese boxing por completo, siendo una de las razones para preferir colecciones genéricas."),
  sqr("¿Cuál es la diferencia clave entre comparar dos structs con `==` (si el struct no sobrecarga el operador) frente a comparar dos referencias de clase con `==` (sin sobrecarga)?","Un struct sin == sobrecargado no compila == a menos que se use Equals/herede de un tipo con soporte; una clase con == por defecto compara referencias, no contenido","Ambos casos comparan siempre el contenido campo por campo automáticamente","Ambos casos comparan siempre solo la referencia en memoria","No hay diferencia, C# trata structs y clases idénticamente en comparaciones",0,"Los structs no tienen `==` definido por defecto (hay que sobrecargarlo o usar Equals, que sí compara campo por campo vía reflexión salvo que se optimice); las clases heredan Equals/== de object, que por defecto compara identidad de referencia."),
  sqr("¿Qué diferencia hay entre pasar un struct por valor a un método y pasarlo con el modificador `ref`?","Sin ref, el método recibe una copia y los cambios no se reflejan afuera; con ref, el método opera sobre la variable original y los cambios sí persisten","Ambos casos son idénticos en C#","ref solo aplica a tipos de referencia, nunca a structs","Sin ref, los cambios siempre se reflejan afuera igualmente",0,"Los value types se pasan por valor por defecto (copia); ref hace que el parámetro sea un alias de la variable original, permitiendo que las modificaciones dentro del método se vean reflejadas en el llamador."),
  sqr("¿Qué imprime este código?\nint x = 10;\nint y = x;\ny = 20;\nConsole.WriteLine(x);","10, porque int es un value type y y = x copia el valor, sin compartir referencia","20, porque x e y apuntan al mismo valor en memoria","Error de compilación","0, porque y sobrescribe x",0,"int es un value type; la asignación y = x copia el valor. Cambiar y después no afecta a x.","int x = 10;\nint y = x;\ny = 20;\nConsole.WriteLine(x);"),
  sqr("¿Cuál es la trampa de entrevista sobre `string` en C# respecto a mutabilidad?","Aunque string es un reference type, es inmutable: cualquier operación que 'modifica' un string realmente crea uno nuevo","string es un value type que se comporta como reference type solo en apariencia","string es completamente mutable como un StringBuilder","Modificar un string en C# nunca reserva memoria adicional",0,"string es una clase (reference type) pero inmutable: métodos como Replace o Substring devuelven un nuevo string en vez de modificar el original, una distinción clásica preguntada en entrevistas."),
  sqr("¿Qué diferencia hay entre `default(int)` y `default(string)`?","default(int) es 0 (el value type tiene un valor por defecto no nulo); default(string) es null (los reference types por defecto son null)","Ambos son siempre null","Ambos son siempre 0","default(string) lanza una excepción en tiempo de compilación",0,"Los value types tienen un valor por defecto propio (0, false, etc.); los reference types tienen null como valor por defecto al no haber sido inicializados."),
  sqr("¿Qué tipo de dato conviene usar para representar dinero de forma precisa en C#, evitando errores de redondeo de punto flotante binario?","decimal, porque usa una representación en base 10 diseñada para cálculos financieros con menor error de redondeo que double/float","double, porque siempre es más preciso que decimal","float, porque ocupa menos memoria y eso mejora la precisión","int, porque los enteros no tienen errores de redondeo en ningún cálculo monetario",1,"decimal está diseñado específicamente para cálculos financieros y decimales exactos en base 10; double/float usan representación binaria de punto flotante, propensa a errores de redondeo inaceptables en dinero."),
  sqr("Trampa de entrevista: ¿es cierto que comparar dos objetos de una misma clase (sin sobrecargar Equals) con `.Equals()` siempre compara sus propiedades una por una?","No; por defecto, Equals heredado de object compara identidad de referencia (si son el mismo objeto en memoria), no el contenido de las propiedades, salvo que la clase sobrescriba Equals","Sí, Equals siempre compara contenido campo por campo en cualquier clase de C#","Sí, pero solo si la clase implementa IComparable","No, Equals siempre lanza una excepción en clases no selladas",0,"Una trampa común es asumir igualdad estructural por defecto; sin sobrescribir Equals (y GetHashCode), dos instancias con las mismas propiedades no serán iguales según Equals, porque compara identidad de referencia."),
 ]},
 {id:"n11-oop-solid",title:"POO y SOLID",summary:"Preguntas de entrevista sobre pilares de la programación orientada a objetos (encapsulamiento, herencia, polimorfismo, abstracción) y los principios SOLID aplicados a diseño de clases en C#, incluyendo violaciones típicas que los entrevistadores piden identificar.",code:"public interface INotifier { void Send(string message); }\npublic class EmailNotifier : INotifier {\n  public void Send(string message) => Console.WriteLine($\"Email: {message}\");\n}\npublic class OrderService {\n  private readonly INotifier _notifier;\n  public OrderService(INotifier notifier) => _notifier = notifier;\n  public void Complete() => _notifier.Send(\"Orden completada\");\n}",questions:[
  sqr("¿Qué principio SOLID ilustra `OrderService` al depender de la abstracción `INotifier` en vez de instanciar `EmailNotifier` directamente dentro de la clase?","Dependency Inversion Principle (DIP): depender de abstracciones, no de implementaciones concretas","Single Responsibility Principle, porque OrderService solo hace una cosa","Open/Closed Principle, porque no se puede modificar OrderService","Liskov Substitution Principle, porque EmailNotifier hereda de una clase base",0,"DIP establece que los módulos de alto nivel no deben depender de módulos de bajo nivel concretos, sino de abstracciones; aquí OrderService depende de la interfaz INotifier, no de una implementación específica."),
  sqr("Si `EmailNotifier` lanzara una excepción cada vez que se le pasa un mensaje vacío, mientras que otras implementaciones de `INotifier` lo aceptan sin problema, ¿qué principio SOLID se estaría violando potencialmente?","Liskov Substitution Principle (LSP): una subclase/implementación no debería cambiar el comportamiento esperado del contrato de forma incompatible con otras implementaciones","Single Responsibility Principle","Interface Segregation Principle","Open/Closed Principle",0,"LSP exige que cualquier implementación de una abstracción pueda sustituir a otra sin romper las expectativas del código cliente; un comportamiento inesperadamente más restrictivo en una implementación viola ese principio."),
  sqr("¿Qué significa el Open/Closed Principle (OCP) aplicado a `INotifier` y sus implementaciones?","El sistema debe permitir agregar nuevas formas de notificación (por ejemplo SmsNotifier) sin modificar el código existente de OrderService","Las clases deben estar siempre abiertas para modificación directa de su código fuente","Ninguna clase puede implementar más de una interfaz","Todas las clases deben ser selladas (sealed) para cumplir OCP",0,"OCP busca que el comportamiento se extienda agregando nuevo código (nuevas implementaciones de INotifier) en vez de modificar clases ya probadas como OrderService."),
  sqr("¿Qué violación del Single Responsibility Principle (SRP) sería agregar lógica de persistencia en base de datos directamente dentro de `OrderService.Complete()`, además de la notificación?","OrderService tendría dos razones para cambiar (lógica de notificación y lógica de persistencia), mezclando responsabilidades que deberían estar separadas","Ninguna, SRP permite cualquier cantidad de responsabilidades en una clase mientras compile","Sería una violación de Liskov, no de SRP","SRP solo aplica a interfaces, nunca a clases concretas",0,"SRP indica que una clase debe tener una única razón para cambiar; mezclar notificación y persistencia en la misma clase acopla responsabilidades independientes, dificultando el mantenimiento."),
  sqr("¿Qué es el Interface Segregation Principle (ISP) y qué problema evita respecto a interfaces grandes como una hipotética `INotifier` con 10 métodos, donde una implementación solo necesita 2?","ISP recomienda interfaces pequeñas y específicas, evitando forzar a una clase a implementar métodos que no necesita o no puede soportar razonablemente","ISP exige que toda interfaz tenga exactamente un solo método sin excepción","ISP indica que las interfaces deben fusionarse en una sola interfaz general por proyecto","ISP prohíbe el uso de interfaces junto con clases abstractas",0,"ISP busca evitar 'interfaces gordas' que fuerzan a los implementadores a proveer métodos irrelevantes para ellos, típicamente lanzando NotImplementedException, una señal de diseño problemático."),
  sqr("¿Qué diferencia hay entre herencia y composición al diseñar `OrderService` con una dependencia de `INotifier` inyectada por constructor?","Composición (tener una referencia a INotifier) permite cambiar el comportamiento en tiempo de ejecución sin acoplar OrderService a una jerarquía de herencia fija","Herencia siempre es preferible a composición en cualquier escenario de diseño","Composición solo aplica a value types, nunca a interfaces","No hay ninguna diferencia práctica entre ambos enfoques",0,"Inyectar una dependencia (composición, 'has-a') da más flexibilidad que heredar un comportamiento fijo ('is-a'), permitiendo intercambiar implementaciones sin modificar OrderService, alineado con DIP."),
  sqr("¿Qué palabra clave de C# permite que una clase derivada reemplace la implementación de un método marcado como `virtual` en la clase base?","override","new (únicamente)","sealed","abstract",0,"override sobrescribe un miembro virtual heredado, participando en el polimorfismo en tiempo de ejecución; new oculta el miembro sin polimorfismo real, una trampa de entrevista distinta."),
  sqr("Trampa de entrevista: ¿qué diferencia hay entre usar `new` para ocultar un método heredado y usar `override` para sobrescribirlo, al invocar el método a través de una referencia de tipo base?","Con `new`, se ejecuta la versión de la clase base cuando se llama a través de una referencia de tipo base (sin polimorfismo real); con `override`, se ejecuta la versión de la clase derivada (despacho dinámico)","Ambos comportamientos son exactamente idénticos en cualquier escenario","new siempre ejecuta la versión derivada igual que override","override solo funciona con clases selladas (sealed)",0,"Esta es una trampa clásica: `new` oculta el miembro pero el despacho a través de una referencia base sigue resolviéndose estáticamente a la base; `override` participa en el despacho polimórfico dinámico basado en el tipo real del objeto."),
  sqr("¿Qué principio SOLID se relaciona más directamente con usar interfaces e inyección de dependencias para facilitar pruebas unitarias con mocks, como en `OrderService`?","Dependency Inversion Principle (DIP), porque depender de abstracciones permite sustituir la implementación real por un mock en pruebas","Interface Segregation Principle exclusivamente","Liskov Substitution Principle exclusivamente","Ningún principio SOLID se relaciona con pruebas unitarias",0,"DIP es la base que permite testabilidad: al depender de INotifier (abstracción) en vez de EmailNotifier (concreción), se puede inyectar un mock de INotifier en pruebas sin tocar OrderService."),
  sqr("¿Qué antipatrón describe una clase `OrderManager` que valida, calcula impuestos, persiste en base de datos, envía correos y genera reportes, todo en la misma clase?","Una violación de Single Responsibility Principle, frecuentemente llamada 'God Object' o clase 'todopoderosa'","Un ejemplo correcto de Open/Closed Principle bien aplicado","Una implementación válida de Interface Segregation Principle","Un patrón recomendado llamado 'Facade obligatorio'",0,"Concentrar múltiples responsabilidades no relacionadas en una sola clase es un antipatrón clásico ('God Object') que viola SRP y dificulta el mantenimiento, las pruebas y la reutilización."),
 ]},
 {id:"n11-linq-collections",title:"LINQ y colecciones",summary:"Preguntas de entrevista sobre LINQ: ejecución diferida (deferred execution) vs inmediata, diferencias entre IEnumerable e IQueryable, y trampas comunes al combinar operadores LINQ con colecciones mutables o closures dentro de bucles.",code:"var numbers = new List<int> { 1, 2, 3 };\nvar query = numbers.Where(n => n > 1); // no se ejecuta todavía\nnumbers.Add(4);\nforeach (var n in query) Console.Write(n + \" \"); // ?",questions:[
  sqr("¿Qué imprime el foreach del ejemplo, sabiendo que `numbers.Add(4)` ocurre después de definir `query` pero antes de iterarla?","2 3 4, porque Where usa ejecución diferida: la consulta se evalúa al iterarla, incluyendo el elemento agregado después","2 3, porque query se congela con los valores que existían al momento de crearla","1 2 3 4, porque Where no filtra nada por ejecución diferida","Error en tiempo de ejecución por modificar la colección tras crear la query",0,"LINQ con IEnumerable usa ejecución diferida: Where no se ejecuta hasta que se itera la consulta (en el foreach). Como numbers ya incluye el 4 en ese momento, y 4 > 1, aparece en el resultado."),
  sqr("¿Qué diferencia clave hay entre `IEnumerable<T>` e `IQueryable<T>` al usar Entity Framework Core?","IQueryable construye una expresión que se traduce y ejecuta en la base de datos (por ejemplo como SQL); IEnumerable ejecuta la lógica en memoria del lado del cliente tras materializar los datos","Son exactamente intercambiables sin ninguna diferencia de comportamiento o rendimiento","IEnumerable siempre es más eficiente que IQueryable en cualquier escenario con EF Core","IQueryable solo puede usarse con colecciones en memoria, nunca con bases de datos",0,"IQueryable permite que el proveedor (como EF Core) traduzca la consulta a SQL y la ejecute en la base de datos; si se convierte a IEnumerable antes de tiempo (por ejemplo con AsEnumerable o ToList), el resto de la lógica LINQ se ejecuta en memoria, del lado del cliente."),
  sqr("¿Cuál es la trampa clásica al usar `.ToList()` demasiado pronto en una consulta LINQ sobre un DbSet de EF Core, antes de aplicar un `.Where(...)` adicional?","Fuerza a traer todos los registros de la base de datos a memoria antes de filtrar, en vez de dejar que el filtro se traduzca a SQL y se aplique en el servidor de base de datos","ToList() mejora automáticamente el rendimiento de cualquier consulta LINQ","No tiene ningún efecto en el rendimiento, solo cambia el tipo de retorno","ToList() impide aplicar cualquier operador LINQ adicional después",0,"Llamar a ToList() antes de terminar de construir el filtro materializa la consulta completa en memoria (todo el conjunto), perdiendo la posibilidad de que Where se traduzca y ejecute eficientemente en la base de datos."),
  sqr("¿Qué diferencia hay entre `First()` y `FirstOrDefault()` cuando la secuencia no contiene ningún elemento que cumpla la condición?","First() lanza una excepción (InvalidOperationException); FirstOrDefault() devuelve el valor por defecto del tipo (por ejemplo null o 0) sin lanzar excepción","Ambos lanzan siempre una excepción si no hay coincidencias","Ambos devuelven siempre null sin importar el tipo","First() devuelve el valor por defecto; FirstOrDefault() lanza la excepción",0,"First() asume que debe existir al menos un elemento y lanza si la secuencia está vacía; FirstOrDefault() maneja ese caso devolviendo default(T) en vez de lanzar una excepción."),
  sqr("¿Qué imprime este código?\nvar actions = new List<Action>();\nfor (int i = 0; i < 3; i++) {\n  actions.Add(() => Console.Write(i + \" \"));\n}\nforeach (var a in actions) a();","0 1 2, porque en C# moderno cada iteración del for captura una variable de bucle distinta","2 2 2, porque todas las lambdas capturan la misma variable i por referencia","0 0 0, porque cada lambda captura el valor inicial de i","Error de compilación por capturar una variable de bucle en una lambda",0,"Desde C# 5, la variable de iteración de un `for` se re-declara implícitamente en cada vuelta cuando se usa en closures, por lo que cada lambda captura su propio valor de i (comportamiento distinto al de versiones anteriores de C#, una trampa de entrevista clásica).","var actions = new List<Action>();\nfor (int i = 0; i < 3; i++) {\n  actions.Add(() => Console.Write(i + \" \"));\n}\nforeach (var a in actions) a();"),
  sqr("¿Qué produce `numbers.Select(n => n * 2).Where(n => n > 4).ToList()` sobre `numbers = new List<int>{1,2,3,4}`?","Una lista con 6 y 8, porque primero se duplica cada valor (2,4,6,8) y luego se filtran los mayores a 4","Una lista con 2 y 4, aplicando Where antes que Select","Una lista vacía, porque Select y Where no pueden encadenarse","Una lista con 1,2,3,4 sin cambios, porque ToList ignora los operadores previos",0,"Los operadores LINQ se aplican en el orden en que se encadenan: primero Select duplica cada valor (2,4,6,8), luego Where filtra los mayores a 4, dejando 6 y 8.","var numbers = new List<int>{1,2,3,4};\nvar result = numbers.Select(n => n * 2).Where(n => n > 4).ToList();"),
  sqr("¿Por qué modificar una `List<T>` mientras se está iterando sobre ella con un `foreach` lanza `InvalidOperationException`?","Porque foreach usa un enumerador que detecta cambios en la colección subyacente durante la iteración y la invalida para evitar comportamiento indefinido","Porque foreach nunca puede iterar sobre List<T>, solo sobre arrays","Porque C# prohíbe declarar variables dentro de un foreach","Porque List<T> es de solo lectura una vez creada",0,"El enumerador de List<T> valida una versión interna de la colección; si detecta que fue modificada estructuralmente (Add/Remove) durante la iteración, lanza InvalidOperationException para prevenir comportamiento indefinido."),
  sqr("¿Qué diferencia hay entre `Select` y `SelectMany` en LINQ al trabajar con una colección de colecciones (por ejemplo, `List<List<int>>`)?","Select produce una secuencia de secuencias (una colección anidada por cada elemento); SelectMany aplana el resultado en una única secuencia de elementos","Ambos producen exactamente el mismo resultado siempre","SelectMany solo funciona con IQueryable, nunca con IEnumerable","Select siempre aplana automáticamente colecciones anidadas",0,"Select transforma cada elemento uno a uno (preservando la estructura anidada si el resultado es otra colección); SelectMany aplana esas colecciones intermedias en una sola secuencia plana de resultados."),
  sqr("¿Qué método LINQ es apropiado para verificar si al menos un elemento de una colección cumple una condición, sin materializar toda la colección filtrada?","Any(predicado)","Where(predicado).Count() > 0 (como única opción válida)","Select(predicado)","ToList().Contains(predicado)",0,"Any(predicado) es más eficiente porque se detiene en el primer elemento que cumple la condición, sin necesidad de recorrer o materializar toda la colección como haría Where().Count()."),
  sqr("Trampa de entrevista: ¿es correcto asumir que una consulta LINQ definida con `var query = dbSet.Where(...)` ya se ejecutó contra la base de datos apenas se escribe esa línea?","No; con IQueryable la consulta se difiere hasta que se materializa explícitamente (con ToList, ToArray, First, foreach, etc.), momento en el que se traduce y ejecuta contra la base de datos","Sí, cualquier expresión LINQ se ejecuta inmediatamente en el momento en que se declara","Sí, pero solo si se usa Where en vez de Select","No, la consulta nunca se ejecuta hasta que se cierra la aplicación",0,"La ejecución diferida es central en LINQ: definir la consulta solo construye una expresión (o un árbol de expresión con IQueryable); la ejecución real ocurre al enumerar o materializar el resultado, un concepto frecuentemente mal entendido."),
 ]},
 {id:"n11-async-concurrency",title:"Async y concurrencia",summary:"Preguntas de entrevista sobre async/await en C#: por qué async void es peligroso salvo en manejadores de eventos, deadlocks clásicos al bloquear código async con .Result o .Wait(), diferencias entre Task.Run y async I/O, y el propósito de ConfigureAwait(false) en librerías.",code:"public async void ButtonClick(object sender, EventArgs e) {\n  await ProcessAsync(); // excepciones aquí no se pueden capturar afuera\n}\n\npublic async Task<int> GetValueAsync() {\n  await Task.Delay(100);\n  return 42;\n}\n\n// Código síncrono llamando a async (trampa de deadlock en algunos contextos):\nvar result = GetValueAsync().Result;",questions:[
  sqr("¿Por qué `async void` se considera peligroso en general, salvo en manejadores de eventos como `ButtonClick`?","Porque las excepciones lanzadas dentro de un método async void no pueden ser capturadas por el código llamador con un try/catch normal, y pueden terminar el proceso","Porque async void es más lento que async Task en todos los casos","Porque el compilador rechaza cualquier uso de async void fuera de manejadores de eventos","Porque async void impide usar await dentro del método",0,"Un método async Task propaga sus excepciones a través de la Task devuelta, permitiendo capturarlas con await/try-catch en el llamador; async void no tiene una Task que observar, así que las excepciones se propagan de forma no controlada, típicamente terminando la aplicación."),
  sqr("¿Por qué `GetValueAsync().Result` puede causar un deadlock en ciertos contextos (por ejemplo, en código de UI clásico o ASP.NET clásico con SynchronizationContext)?","Porque .Result bloquea el hilo actual esperando la Task, y si el contexto de sincronización requiere ese mismo hilo para continuar tras el await interno, ninguno de los dos puede avanzar","Porque Task.Delay nunca completa en entornos con SynchronizationContext","Porque .Result siempre lanza una excepción antes de poder bloquear el hilo","Porque GetValueAsync no puede ejecutarse fuera de un método async",0,"En contextos con un SynchronizationContext que captura y reutiliza el hilo original (como UI de escritorio o ASP.NET clásico), bloquear ese hilo con .Result mientras el await interno espera volver a ese mismo hilo produce un deadlock clásico."),
  sqr("¿Qué diferencia hay entre `Task.Run(() => Compute())` y simplemente `await ComputeAsync()` cuando `ComputeAsync` realiza una operación de I/O (como una llamada HTTP)?","Task.Run mueve el trabajo a un hilo del thread pool (útil para CPU-bound); para I/O-bound, await ComputeAsync() ya libera el hilo mientras espera, sin necesitar un hilo adicional dedicado","Ambos son exactamente equivalentes en cualquier escenario de I/O o CPU","Task.Run siempre es más rápido que await para cualquier tipo de operación","await ComputeAsync() bloquea el hilo igual que una llamada síncrona",1,"Para trabajo de I/O verdaderamente asíncrono (como HttpClient), await ya libera el hilo mientras se espera la respuesta, sin bloquear ni necesitar un hilo del pool; Task.Run es más apropiado para trabajo CPU-bound que se quiere descargar del hilo actual."),
  sqr("¿Qué logra `ConfigureAwait(false)` al usarse dentro de una librería que no necesita volver al contexto de sincronización original tras un await?","Evita capturar y volver forzosamente al SynchronizationContext original tras el await, lo que puede reducir el riesgo de deadlocks y mejorar el rendimiento en ciertos escenarios","Hace que el método deje de ser asíncrono y se ejecute de forma síncrona","Cancela automáticamente la tarea si tarda demasiado en completar","Convierte el método en async void automáticamente",0,"ConfigureAwait(false) indica que la continuación después del await no necesita ejecutarse en el contexto original (por ejemplo el hilo de UI); es una práctica común en código de librería que no interactúa con UI, aunque en ASP.NET Core moderno (sin SynchronizationContext por defecto) su impacto es menor."),
  sqr("¿Qué tipo de retorno debería tener un método async que no necesita devolver ningún valor, siguiendo las mejores prácticas (evitando async void)?","Task","void","async void siempre que sea posible","object",0,"Un método async sin valor de retorno debería devolver Task (no void), permitiendo que el llamador use await y observe/maneje excepciones correctamente, salvo el caso específico de manejadores de eventos."),
  sqr("¿Qué pasa si dentro de un método async se olvida usar `await` antes de llamar a otro método async, por ejemplo escribiendo `ProcessAsync();` en vez de `await ProcessAsync();`?","La tarea se dispara pero no se espera ('fire and forget' accidental); el método continúa sin esperar su finalización y las excepciones dentro de esa tarea pueden perderse silenciosamente","El compilador convierte automáticamente la llamada en síncrona","Es exactamente equivalente a usar await, sin ninguna diferencia de comportamiento","El programa no compila si falta await antes de una llamada async",0,"Sin await, la Task devuelta se ignora: el código continúa inmediatamente sin esperar la operación asíncrona, y cualquier excepción que ocurra dentro de esa tarea no propagada puede pasar desapercibida, un bug sutil y frecuente."),
  sqr("¿Qué diferencia hay entre paralelismo y concurrencia en el contexto de programación asíncrona en C#?","Concurrencia es manejar múltiples tareas que progresan de forma intercalada (posiblemente en un solo hilo, como con async/await esperando I/O); paralelismo implica ejecución simultánea real en múltiples núcleos/hilos","Son sinónimos exactos sin ninguna diferencia técnica","Paralelismo solo aplica a bases de datos; concurrencia solo aplica a interfaces gráficas","Concurrencia requiere siempre múltiples procesadores físicos",0,"async/await con I/O no necesariamente usa múltiples hilos simultáneos: logra concurrencia liberando el hilo mientras se espera una operación externa; el paralelismo real (por ejemplo con Parallel.ForEach o Task.Run para CPU-bound) sí usa múltiples núcleos ejecutando trabajo simultáneamente."),
  sqr("¿Qué mecanismo de C# se usa típicamente para cancelar una operación asíncrona en curso de forma cooperativa, como una solicitud HTTP con timeout configurable?","CancellationToken, pasado a métodos async y verificado periódicamente o respetado por operaciones como HttpClient","try/catch únicamente, sin ningún mecanismo adicional","Thread.Abort() sobre el hilo que ejecuta la tarea asíncrona","Task.Kill(), un método estándar de la clase Task",0,"CancellationToken (junto con CancellationTokenSource) es el mecanismo estándar y cooperativo para señalar cancelación; las operaciones async compatibles verifican el token y pueden terminar limpiamente arrojando OperationCanceledException."),
  sqr("¿Qué imprime este método si se le hace `await` correctamente, sabiendo que Task.Delay no bloquea el hilo?\nasync Task<string> GetDataAsync() {\n  await Task.Delay(10);\n  return \"listo\";\n}","\"listo\", después de que la espera asíncrona de 10ms se completa, sin haber bloqueado el hilo mientras tanto","\"listo\", pero solo si se ejecuta dentro de un método Main síncrono tradicional","Ninguna salida, porque Task.Delay bloquea indefinidamente","Un error de compilación porque falta ConfigureAwait",0,"Task.Delay(10) crea una espera asíncrona no bloqueante; tras completarse (sin ocupar el hilo durante la espera), el método continúa y retorna el string 'listo' a través de la Task<string>.","async Task<string> GetDataAsync() {\n  await Task.Delay(10);\n  return \"listo\";\n}"),
  sqr("Trampa de entrevista: ¿es correcto decir que `async`/`await` en C# siempre crea hilos nuevos para ejecutar el código asíncrono?","No; async/await no crea hilos nuevos por sí mismo para operaciones de I/O asíncronas reales (como llamadas de red), ya que aprovecha operaciones que no requieren bloquear un hilo mientras se espera","Sí, cada await siempre crea y usa un hilo nuevo del thread pool sin excepción","Sí, pero solo en aplicaciones de consola, nunca en ASP.NET Core","No, async/await nunca puede usarse junto con operaciones de red",0,"Una confusión frecuente es asumir que async implica multithreading. Para I/O-bound real, no hay un hilo dedicado ocupado durante la espera; el hilo se libera y solo se retoma al completarse la operación, a diferencia de Task.Run que sí usa explícitamente un hilo del thread pool."),
 ]},
 {id:"n11-apis-efcore",title:"APIs y EF Core",summary:"Preguntas de entrevista sobre diseño de APIs ASP.NET Core y Entity Framework Core: códigos de estado HTTP correctos, tracking vs no-tracking en consultas, el problema N+1, y trampas de concurrencia y ciclo de vida del DbContext.",code:"public class ProductsController : ControllerBase {\n  private readonly AppDbContext _db;\n  public ProductsController(AppDbContext db) => _db = db;\n\n  [HttpGet(\"{id}\")]\n  public async Task<ActionResult<Product>> Get(int id) {\n    var product = await _db.Products.FindAsync(id);\n    if (product is null) return NotFound();\n    return Ok(product);\n  }\n}",questions:[
  sqr("¿Qué código de estado HTTP debería devolver un endpoint GET cuando el recurso solicitado no existe, como implementa `Get` en el ejemplo con `NotFound()`?","404 Not Found","400 Bad Request","200 OK con un cuerpo vacío","500 Internal Server Error",0,"404 comunica correctamente que el recurso identificado por ese id no existe; NotFound() en ASP.NET Core produce exactamente ese código de estado."),
  sqr("¿Qué diferencia hay entre `_db.Products.FindAsync(id)` y `_db.Products.Where(p => p.Id == id).FirstOrDefaultAsync()` en EF Core, cuando la entidad ya está siendo trackeada en el contexto?","FindAsync primero busca en la memoria local del contexto (tracked entities) antes de ir a la base de datos, evitando una consulta SQL innecesaria si la entidad ya está cargada","Ambos son exactamente equivalentes en cualquier escenario sin ninguna diferencia de comportamiento","Where().FirstOrDefaultAsync() siempre es más rápido que FindAsync","FindAsync nunca puede usarse con claves compuestas",0,"FindAsync tiene la optimización de revisar primero el ChangeTracker local por clave primaria antes de consultar la base de datos, algo que Where().FirstOrDefaultAsync() no hace (siempre genera una consulta)."),
  sqr("¿Qué es el problema N+1 en el contexto de EF Core, por ejemplo al iterar una lista de órdenes y acceder a `order.Customer.Name` sin haber incluido esa relación?","Se ejecuta una consulta para obtener las órdenes y luego una consulta adicional por cada orden para cargar su Customer, generando N+1 consultas en vez de una sola optimizada","EF Core siempre carga automáticamente todas las relaciones sin generar consultas adicionales","Es un error de compilación que impide ejecutar el programa","Solo ocurre si se usa AsNoTracking() en la consulta principal",0,"Sin usar Include (eager loading) o proyección adecuada, acceder a una propiedad de navegación dispara lazy loading (si está habilitado) por cada entidad, generando una consulta adicional por cada fila, un patrón de rendimiento clásico a evitar."),
  sqr("¿Qué método de EF Core soluciona el problema N+1 cargando explícitamente una relación en la misma consulta inicial, por ejemplo `_db.Orders.Include(o => o.Customer).ToListAsync()`?","Include (eager loading), que genera un JOIN o consultas adicionales optimizadas para traer la relación junto con la entidad principal en la misma operación","FindAsync, que nunca puede cargar relaciones","AsNoTracking, que deshabilita por completo la carga de relaciones","Remove, que elimina la relación de la base de datos",0,"Include indica a EF Core que cargue esa propiedad de navegación como parte de la misma consulta (eager loading), evitando la cascada de consultas individuales del problema N+1."),
  sqr("¿Qué ventaja de rendimiento aporta `AsNoTracking()` en una consulta de EF Core usada solo para lectura, como listar productos en un endpoint GET?","Evita el overhead de que EF Core registre las entidades en el ChangeTracker para detectar cambios, mejorando el rendimiento cuando no se van a modificar ni guardar esas entidades","Hace que la consulta se ejecute completamente en memoria sin tocar la base de datos","Elimina automáticamente los duplicados del resultado","Convierte la consulta en asíncrona automáticamente",0,"AsNoTracking evita el costo de trackear cambios sobre las entidades devueltas, apropiado para escenarios de solo lectura donde no habrá un SaveChanges posterior sobre esas mismas instancias."),
  sqr("¿Por qué es problemático registrar un `DbContext` con tiempo de vida `Singleton` en el contenedor de DI de una API ASP.NET Core?","DbContext no está diseñado para ser thread-safe ni de larga duración; compartir una única instancia entre solicitudes concurrentes puede causar comportamiento incorrecto o excepciones","No hay ningún problema, Singleton siempre es la mejor opción de ciclo de vida para cualquier servicio","DbContext solo puede registrarse como Transient, nunca de otra forma","Singleton mejora automáticamente el rendimiento de las consultas sin ningún riesgo",0,"DbContext está pensado para tener una vida corta (típicamente por solicitud, 'Scoped') y no es seguro para uso concurrente entre hilos; usarlo como Singleton expone la app a condiciones de carrera y estados inconsistentes."),
  sqr("¿Qué código de estado HTTP es más apropiado para un endpoint POST que crea exitosamente un nuevo recurso, siguiendo las convenciones REST (por ejemplo usando `CreatedAtAction`)?","201 Created, incluyendo idealmente la ubicación (header Location) del recurso creado","200 OK sin ninguna información adicional","204 No Content, sin retornar ningún dato del recurso creado","202 Accepted, indicando que el recurso se creará en el futuro",0,"201 Created es la convención REST estándar para una creación exitosa, comunicando además (vía el header Location) dónde puede consultarse el nuevo recurso."),
  sqr("¿Qué excepción típica de EF Core señala un conflicto de concurrencia optimista, por ejemplo cuando dos usuarios intentan actualizar la misma fila que cambió entre la lectura y el SaveChanges?","DbUpdateConcurrencyException","DbUpdateException genérica sin distinción de causa","InvalidOperationException siempre","TimeoutException únicamente",0,"DbUpdateConcurrencyException se lanza específicamente cuando EF Core detecta (usualmente vía una columna de concurrencia como RowVersion) que la fila fue modificada por otro proceso desde que se cargó, señalando un conflicto de concurrencia optimista."),
  sqr("¿Qué código de estado HTTP debería devolver una API cuando el cliente envía un cuerpo de solicitud que falla la validación del modelo (por ejemplo, un campo requerido ausente)?","400 Bad Request","404 Not Found","500 Internal Server Error","401 Unauthorized",0,"400 comunica que la solicitud del cliente es inválida por sí misma (datos mal formados o que no pasan validación), a diferencia de errores del servidor (500) o de recursos inexistentes (404)."),
  sqr("Trampa de entrevista: si un endpoint GET modifica datos en la base de datos como efecto secundario (por ejemplo, incrementa un contador de vistas cada vez que se consulta), ¿qué principio de diseño de API se está violando?","La idempotencia y semántica esperada de una solicitud GET, que según las convenciones HTTP no debería producir efectos secundarios visibles ni modificar el estado del servidor","Ninguno, los métodos GET pueden modificar datos libremente sin restricciones","El principio de Liskov Substitution, porque GET hereda de POST","La convención de nombres de ASP.NET Core, únicamente un problema de estilo",0,"Por convención HTTP, GET debe ser una operación segura (sin efectos secundarios) e idempotente; usarla para mutar estado del servidor (como incrementar contadores) rompe expectativas de clientes, proxies y cachés que asumen que GET es de solo lectura."),
 ]},
 {id:"n11-architecture",title:"Arquitectura",summary:"Preguntas de entrevista sobre arquitectura de software en el contexto .NET: capas (presentación, negocio, datos), arquitectura limpia/hexagonal, el patrón repositorio (y cuándo es redundante sobre EF Core), y trade-offs entre monolito y microservicios.",code:"// Capa de dominio (no depende de EF Core ni de ASP.NET Core)\npublic class Order {\n  public int Id { get; private set; }\n  public OrderStatus Status { get; private set; }\n  public void Complete() {\n    if (Status != OrderStatus.Pending) throw new InvalidOperationException(\"Solo se puede completar una orden pendiente\");\n    Status = OrderStatus.Completed;\n  }\n}",questions:[
  sqr("¿Qué principio de arquitectura limpia/hexagonal ilustra que la clase `Order` (dominio) no referencie EF Core ni ASP.NET Core?","La capa de dominio debe ser independiente de detalles de infraestructura (base de datos, framework web), dependiendo la infraestructura del dominio y no al revés","El dominio siempre debe depender directamente de Entity Framework Core para funcionar correctamente","No existe ninguna regla real sobre las dependencias entre capas de dominio e infraestructura","ASP.NET Core debe estar referenciado en todas las capas para que el proyecto compile",0,"Un pilar de arquitectura limpia/hexagonal es que las reglas de negocio (dominio) no dependan de detalles externos como el framework web o el ORM; son las capas externas (infraestructura) las que dependen del dominio, no al revés."),
  sqr("¿Qué ventaja aporta que la lógica de negocio esté encapsulada en el método `Complete()` de `Order`, validando la transición de estado, en vez de dejar que cualquier capa externa cambie `Status` libremente?","Protege las invariantes del dominio (por ejemplo, no completar una orden que no está pendiente) sin importar desde dónde se use la entidad, evitando estados inválidos dispersos por el código","Hace que la clase Order sea más lenta en tiempo de ejecución","Elimina la necesidad de cualquier prueba unitaria sobre Order","Impide que Order se persista alguna vez en una base de datos",0,"Encapsular las reglas de transición de estado dentro del propio agregado/entidad (en vez de un setter público libre) es un principio central de diseño orientado al dominio: las invariantes se protegen centralizadamente, sin depender de que cada consumidor externo las respete manualmente."),
  sqr("¿Cuándo se considera que el patrón Repository sobre EF Core puede ser redundante en vez de aportar valor real?","Cuando simplemente envuelve DbSet<T> con métodos casi idénticos (Add, Get, Update) sin agregar lógica ni abstraer realmente la persistencia, dado que DbContext/DbSet ya cumple ese rol de abstracción de acceso a datos","Siempre; el patrón Repository nunca aporta valor en ningún escenario con EF Core","Nunca; el patrón Repository siempre es obligatorio al usar EF Core","Solo cuando el proyecto no tiene pruebas unitarias",0,"Una crítica común y válida es que envolver DbSet<T> con un Repository que solo replica sus métodos sin lógica adicional agrega una capa de indirección sin beneficio real, ya que DbContext/DbSet ya actúa como una unidad de trabajo y abstracción razonable sobre la persistencia."),
  sqr("¿Qué trade-off principal existe al elegir una arquitectura de microservicios en vez de un monolito para un sistema nuevo y pequeño con un equipo reducido?","Los microservicios añaden complejidad operativa (despliegue distribuido, comunicación entre servicios, consistencia de datos) que puede no justificarse para un sistema pequeño con pocos desarrolladores","Los microservicios son siempre más simples de desarrollar y desplegar que un monolito, sin excepción","Un monolito nunca puede escalar ni siquiera verticalmente","No existe ningún trade-off real entre ambos enfoques",0,"Los microservicios aportan beneficios de escalado y despliegue independiente, pero a costa de complejidad operativa significativa (red, consistencia distribuida, observabilidad); para equipos pequeños o sistemas simples, un monolito bien modularizado suele ser más pragmático."),
  sqr("¿Qué es un 'monolito modular' y qué problema busca resolver frente a un monolito tradicional poco estructurado?","Es un monolito organizado en módulos con límites claros y bajo acoplamiento entre ellos, buscando mantenibilidad sin asumir de inmediato la complejidad operativa de microservicios","Es un sinónimo exacto de arquitectura de microservicios sin ninguna diferencia","Es una arquitectura que obliga a usar exactamente un microservicio por tabla de base de datos","Es un patrón exclusivo de aplicaciones sin base de datos",0,"El monolito modular busca los beneficios de organización y bajos acoplamientos de una arquitectura bien diseñada, manteniendo el despliegue simple de un monolito, como paso intermedio razonable antes de (si acaso) migrar a microservicios."),
  sqr("¿Qué capa de una arquitectura en capas típica (presentación, aplicación/negocio, infraestructura/datos) debería contener las reglas de validación de negocio como 'una orden no puede completarse dos veces'?","La capa de negocio/dominio, no la capa de presentación (controladores) ni la de infraestructura (acceso a datos)","La capa de presentación, directamente en el controlador HTTP","La capa de infraestructura, dentro de las clases de acceso a datos","Ninguna capa específica; las reglas de negocio deben repetirse en cada capa",0,"Las reglas de negocio deben vivir en la capa de dominio/negocio para evitar duplicación y garantizar que se apliquen sin importar el punto de entrada (API, job en background, etc.), en vez de quedar dispersas en controladores o en el acceso a datos."),
  sqr("¿Qué ventaja aporta el patrón CQRS (Command Query Responsibility Segregation) al separar explícitamente las operaciones de lectura de las de escritura?","Permite optimizar y evolucionar independientemente los modelos de lectura y escritura (por ejemplo, consultas más simples/optimizadas frente a comandos que aplican reglas de negocio complejas)","Obliga a que lecturas y escrituras usen siempre exactamente la misma base de datos y el mismo modelo","Elimina por completo la necesidad de validar los datos de entrada","Es un patrón exclusivo de aplicaciones sin persistencia en base de datos",0,"CQRS separa el modelo usado para consultas del modelo usado para comandos que modifican estado, permitiendo optimizar cada lado según sus necesidades (por ejemplo, proyecciones de solo lectura vs. agregados con reglas de negocio)."),
  sqr("¿Qué significa que una API HTTP actúe como 'puerto de entrada' (driving adapter) en arquitectura hexagonal, mientras que EF Core actúa como 'adaptador de salida' (driven adapter)?","Ambos son adaptadores externos que interactúan con el núcleo de dominio a través de puertos (interfaces) definidos por el dominio, sin que el dominio dependa de sus detalles concretos","La API HTTP y EF Core son literalmente la misma capa en arquitectura hexagonal","El dominio debe depender directamente de los detalles internos de ASP.NET Core y EF Core","Solo EF Core puede considerarse un adaptador; la API HTTP nunca lo es",0,"En arquitectura hexagonal, tanto la entrada (API HTTP) como la salida (persistencia con EF Core) son adaptadores intercambiables que implementan puertos (interfaces) definidos por el dominio, manteniendo el núcleo de negocio desacoplado de detalles de infraestructura concretos."),
  sqr("¿Qué riesgo corre un sistema que expone directamente sus entidades de EF Core (con propiedades de navegación completas) como respuesta JSON de la API, en vez de usar DTOs específicos?","Puede filtrar datos internos no deseados, generar ciclos de serialización con relaciones circulares, y acoplar fuertemente el contrato público de la API a los detalles del modelo de persistencia","Ninguno; exponer entidades de EF Core directamente es siempre la mejor práctica recomendada","Mejora automáticamente el rendimiento de la serialización JSON","Hace innecesario cualquier tipo de validación de entrada",0,"Exponer entidades de persistencia directamente acopla el contrato público de la API a detalles internos del modelo de datos, puede filtrar información sensible y genera problemas prácticos como ciclos de referencia al serializar relaciones; los DTOs desacoplan y controlan explícitamente qué se expone."),
  sqr("Trampa de entrevista: ¿es cierto que adoptar microservicios resuelve automáticamente los problemas de acoplamiento de un sistema mal diseñado?","No; si los límites entre servicios se definen mal, los microservicios pueden terminar tan (o más) acoplados que un monolito, solo que ahora el acoplamiento ocurre a través de la red, siendo más difícil de diagnosticar","Sí, dividir un sistema en microservicios siempre elimina cualquier problema de acoplamiento existente","Sí, porque cada microservicio es automáticamente independiente sin importar cómo se diseñe","No, porque los microservicios no pueden comunicarse entre sí bajo ninguna circunstancia",0,"Los microservicios no son una solución automática a un mal diseño: si los límites de los servicios no reflejan límites de negocio reales (bounded contexts), el acoplamiento simplemente se traslada a la red, con la complejidad añadida de la comunicación distribuida."),
 ]},
 {id:"n11-live-coding",title:"Live coding",summary:"Preguntas de entrevista orientadas a ejercicios de live coding típicos en C#: predecir la salida de fragmentos de código con trampas sutiles (closures, mutabilidad, orden de evaluación, referencias vs valores) que suelen aparecer en whiteboards o pair-programming de entrevista.",code:"public class Counter {\n  public int Value;\n}\n\nvoid Increment(Counter c) => c.Value++;\n\nvar counter = new Counter { Value = 0 };\nIncrement(counter);\nIncrement(counter);\nConsole.WriteLine(counter.Value); // ?",questions:[
  sqr("¿Qué imprime `Console.WriteLine(counter.Value)` en el ejemplo, tras llamar dos veces a `Increment(counter)`?","2, porque Counter es una clase (reference type) y ambas llamadas modifican el mismo objeto en memoria","0, porque counter se pasa por valor y los cambios no persisten fuera del método","1, porque solo la primera llamada surte efecto","Error de compilación porque Value no es de solo lectura",0,"Counter es una clase; al pasarla como parámetro se pasa una copia de la referencia, pero ambas copias apuntan al mismo objeto en el heap. Modificar c.Value dentro de Increment afecta al objeto compartido, así que ambas llamadas incrementan el mismo Value."),
  sqr("¿Qué imprime este fragmento?\nint[] arr = {1, 2, 3};\nvoid Double(int[] a) { for (int i = 0; i < a.Length; i++) a[i] *= 2; }\nDouble(arr);\nConsole.WriteLine(string.Join(\",\", arr));","2,4,6, porque los arrays son reference types y Double modifica el mismo array compartido","1,2,3, porque el array se pasa por valor y la copia no afecta al original","0,0,0, porque Double reinicia el array a ceros","Error de compilación porque arr es un array de solo lectura",0,"Los arrays en C# son reference types; pasar arr a Double pasa una referencia al mismo array en memoria, por lo que las modificaciones dentro del método afectan directamente al array original.","int[] arr = {1, 2, 3};\nvoid Double(int[] a) { for (int i = 0; i < a.Length; i++) a[i] *= 2; }\nDouble(arr);\nConsole.WriteLine(string.Join(\",\", arr));"),
  sqr("¿Qué imprime este código, considerando el orden de evaluación de los operandos en C#?\nint x = 5;\nint result = x++ + ++x;\nConsole.WriteLine(result);","11, porque x++ usa 5 y luego incrementa a 6; ++x incrementa a 7 primero y usa 7: 5 + 7 = 12... revisar","12, porque x++ evalúa 5 (y x pasa a 6), luego ++x incrementa x a 7 y evalúa 7, dando 5 + 7 = 12","10, porque ambos operadores usan el valor final de x","5, porque solo se evalúa el primer operando",1,"x++ (postfijo) usa el valor actual de x (5) en la expresión y luego incrementa x a 6; después ++x (prefijo) incrementa x a 7 primero y usa ese valor 7 en la expresión. La suma es 5 + 7 = 12.","int x = 5;\nint result = x++ + ++x;\nConsole.WriteLine(result);"),
  sqr("¿Qué imprime este fragmento con strings, dado que string es inmutable?\nstring s = \"hola\";\ns.ToUpper();\nConsole.WriteLine(s);","hola, porque ToUpper() devuelve un nuevo string sin modificar el original, y ese resultado no se asignó a ninguna variable","HOLA, porque ToUpper() modifica el string original in-place","Error de compilación porque los strings no tienen el método ToUpper","Una cadena vacía, porque ToUpper() sin asignar borra el contenido",0,"Como string es inmutable, ToUpper() devuelve un nuevo string con el resultado; al no asignarse ese valor de retorno a ninguna variable, la variable s original permanece sin cambios ('hola').","string s = \"hola\";\ns.ToUpper();\nConsole.WriteLine(s);"),
  sqr("¿Qué imprime este código sobre igualdad de referencias vs contenido en strings?\nstring a = \"test\";\nstring b = \"test\";\nConsole.WriteLine(a == b);\nConsole.WriteLine(ReferenceEquals(a, b));","True y True, porque == en string compara contenido (sobrecargado) y ambos literales suelen internarse (string interning), compartiendo la misma referencia","True y False, porque == siempre compara contenido pero ReferenceEquals nunca puede ser true entre dos strings","False y False, porque los strings nunca son iguales por defecto","True y False siempre, sin excepción, para cualquier par de strings iguales",0,"C# sobrecarga == en string para comparar contenido, dando True. Además, el compilador suele internar literales de string idénticos en tiempo de compilación, por lo que a y b terminan apuntando al mismo objeto interno, haciendo que ReferenceEquals también sea True en este caso concreto.","string a = \"test\";\nstring b = \"test\";\nConsole.WriteLine(a == b);\nConsole.WriteLine(ReferenceEquals(a, b));"),
  sqr("¿Qué imprime este código que usa un `List<int>` pasado a un método que lo reasigna dentro del método?\nvoid Reset(List<int> list) { list = new List<int>(); list.Add(99); }\nvar numbers = new List<int> { 1, 2, 3 };\nReset(numbers);\nConsole.WriteLine(string.Join(\",\", numbers));","1,2,3, porque reasignar el parámetro `list` dentro del método solo cambia la copia local de la referencia, no la variable original numbers","99, porque list y numbers siempre apuntan al mismo objeto incluso tras la reasignación","Vacío, porque Reset() borra el contenido de numbers","Error de compilación porque no se puede reasignar un parámetro",0,"Aunque List<int> es un reference type, el parámetro list se pasa por valor (una copia de la referencia). Reasignar list = new List<int>() dentro del método solo cambia a qué apunta esa copia local; la variable original numbers sigue apuntando a la lista original {1,2,3}.","void Reset(List<int> list) { list = new List<int>(); list.Add(99); }\nvar numbers = new List<int> { 1, 2, 3 };\nReset(numbers);\nConsole.WriteLine(string.Join(\",\", numbers));"),
  sqr("¿Qué imprime este código con un `try/finally` y un `return` dentro del try?\nint Get() {\n  try { return 1; }\n  finally { Console.WriteLine(\"finally\"); }\n}\nConsole.WriteLine(Get());","Se imprime 'finally' y luego 1, porque el bloque finally se ejecuta antes de que el valor de retorno finalmente se entregue al llamador","Solo se imprime 1; finally se omite porque hay un return dentro del try","Se imprime 1 y luego 'finally', en ese orden","Error de compilación porque no se puede usar return dentro de un try con finally",0,"El bloque finally siempre se ejecuta antes de que el método realmente retorne, incluso si hay un return dentro del try; por eso 'finally' se imprime primero y luego, al volver al llamador, se imprime el valor devuelto (1).","int Get() {\n  try { return 1; }\n  finally { Console.WriteLine(\"finally\"); }\n}\nConsole.WriteLine(Get());"),
  sqr("¿Qué imprime este código que compara un int nulleable con un valor usando el operador de coalescencia nula?\nint? maybe = null;\nint result = maybe ?? 10;\nConsole.WriteLine(result);","10, porque ?? devuelve el operando derecho cuando el operando izquierdo es null","0, porque int? siempre tiene 0 como valor por defecto al convertirse","Error de compilación porque int? no puede combinarse con ?? y un int normal","null, porque maybe es null y ?? propaga null",0,"El operador ?? (null-coalescing) devuelve el valor de la izquierda si no es null; si es null (como maybe aquí), devuelve el valor de la derecha, en este caso 10.","int? maybe = null;\nint result = maybe ?? 10;\nConsole.WriteLine(result);"),
  sqr("¿Qué imprime este código con captura de excepciones y jerarquía de tipos?\ntry {\n  throw new ArgumentException(\"malo\");\n} catch (Exception ex) {\n  Console.WriteLine(\"general: \" + ex.Message);\n} catch (ArgumentException ex) {\n  Console.WriteLine(\"específico: \" + ex.Message);\n}","No compila: el catch de Exception (más genérico) está antes que el de ArgumentException (más específico), lo que el compilador rechaza por ser inalcanzable","general: malo, porque Exception siempre se evalúa primero sin importar el orden","específico: malo, porque C# reordena automáticamente los catch del más específico al más genérico","Ambos catch se ejecutan en secuencia, imprimiendo ambos mensajes",0,"C# exige que los bloques catch estén ordenados del tipo más específico al más genérico; poner Exception (clase base de ArgumentException) antes que ArgumentException hace que el segundo catch sea inalcanzable, y el compilador lo marca como error."),
  sqr("Trampa de entrevista de live coding: ¿qué imprime este código con un `switch` sobre un enum al que le falta un caso, sin default?\nenum Estado { Pendiente, Completado, Cancelado }\nvoid Imprimir(Estado e) {\n  switch (e) {\n    case Estado.Pendiente: Console.WriteLine(\"pendiente\"); break;\n    case Estado.Completado: Console.WriteLine(\"completado\"); break;\n  }\n}\nImprimir(Estado.Cancelado);","No imprime nada, porque Estado.Cancelado no coincide con ningún case y no hay un default que lo capture, sin lanzar ninguna excepción","Lanza una excepción en tiempo de ejecución porque falta el caso Cancelado","No compila porque el switch debe cubrir todos los valores del enum obligatoriamente","Imprime 'pendiente' porque es el primer case declarado",0,"Un switch clásico sin default simplemente no hace nada si ningún case coincide; el compilador no obliga (en un switch statement tradicional) a cubrir todos los valores del enum, una trampa sutil que puede ocultar bugs silenciosamente.","enum Estado { Pendiente, Completado, Cancelado }\nvoid Imprimir(Estado e) {\n  switch (e) {\n    case Estado.Pendiente: Console.WriteLine(\"pendiente\"); break;\n    case Estado.Completado: Console.WriteLine(\"completado\"); break;\n  }\n}\nImprimir(Estado.Cancelado);"),
 ]},
 {id:"n11-final-challenge",title:"Simulacro final",summary:"Simulacro final integrador: preguntas de entrevista técnica que combinan fundamentos de C#, POO/SOLID, LINQ, async, APIs/EF Core y arquitectura, tal como aparecerían mezcladas en una entrevista real de nivel intermedio para un puesto de desarrollador .NET.",code:"public interface IOrderRepository {\n  Task<Order?> FindAsync(int id);\n  Task SaveAsync(Order order);\n}\n\npublic class CompleteOrderHandler {\n  private readonly IOrderRepository _repo;\n  public CompleteOrderHandler(IOrderRepository repo) => _repo = repo;\n\n  public async Task HandleAsync(int orderId) {\n    var order = await _repo.FindAsync(orderId)\n      ?? throw new InvalidOperationException(\"Orden no encontrada\");\n    order.Complete();\n    await _repo.SaveAsync(order);\n  }\n}",questions:[
  sqr("¿Qué principio SOLID permite que `CompleteOrderHandler` pueda probarse unitariamente sustituyendo `IOrderRepository` por un fake o mock, sin tocar una base de datos real?","Dependency Inversion Principle: la clase depende de la abstracción IOrderRepository, no de una implementación concreta de persistencia","Liskov Substitution Principle exclusivamente","Interface Segregation Principle exclusivamente","Ningún principio SOLID; es solo una casualidad del diseño",0,"Depender de la interfaz IOrderRepository (en vez de una clase concreta de acceso a datos) es lo que permite inyectar una implementación de prueba (fake/mock) sin cambiar CompleteOrderHandler, la esencia de DIP."),
  sqr("En `HandleAsync`, ¿qué patrón expresa `await _repo.FindAsync(orderId) ?? throw new InvalidOperationException(...)`?","Usa el operador ?? junto con una expresión throw para lanzar una excepción de forma concisa cuando el resultado async es null, evitando un if explícito","Es un error de sintaxis porque throw no puede usarse como expresión en C#","Ignora el resultado de FindAsync y siempre lanza la excepción","Convierte automáticamente el método en async void",0,"Desde C# 7, throw puede usarse como expresión; combinado con ??, permite lanzar una excepción de forma compacta cuando el operando izquierdo (aquí, el resultado de FindAsync) es null, sin necesitar un bloque if separado."),
  sqr("¿Qué ocurre si se olvida el `await` antes de `_repo.SaveAsync(order)` dentro de `HandleAsync`?","HandleAsync podría completarse (o su Task marcarse como tal) antes de que SaveAsync realmente termine, arriesgando que el llamador continúe asumiendo que la orden ya se guardó cuando tal vez no ha terminado","No hay ninguna diferencia observable en ningún escenario","El código no compila si falta await antes de una llamada async","SaveAsync se ejecuta de forma síncrona automáticamente al omitir await",0,"Sin await, la Task de SaveAsync se dispara pero no se espera dentro de HandleAsync; el método podría continuar (y su propia Task completarse) sin garantizar que el guardado haya terminado, un bug de sincronización sutil y frecuente."),
  sqr("Si `Order.Complete()` lanza `InvalidOperationException` cuando el estado no es Pendiente, ¿qué código de estado HTTP sería razonable que un controlador ASP.NET Core devolviera al capturar esa excepción específica en este flujo de negocio?","409 Conflict (o 400 Bad Request), comunicando que la operación no es válida dado el estado actual del recurso, no un error inesperado del servidor","500 Internal Server Error, tratándolo siempre como un fallo no controlado del servidor","200 OK, ignorando la excepción y respondiendo como si la operación hubiera tenido éxito","404 Not Found, aunque la orden sí existe",0,"Una violación de una regla de negocio conocida (intentar completar una orden que no está pendiente) es un error del cliente en cuanto al estado esperado del recurso, mejor representado con 409 Conflict o 400, no con un 500 genérico reservado para fallos inesperados del servidor."),
  sqr("¿Qué ventaja de LINQ permitiría escribir `orders.Where(o => o.Status == OrderStatus.Pending).Select(o => o.Id)` para obtener solo los ids de órdenes pendientes de una lista en memoria, en vez de recorrerla manualmente con un bucle for?","Expresividad declarativa: describe qué se quiere obtener (filtrar y proyectar) sin escribir manualmente la lógica de iteración, siendo más legible y menos propenso a errores de índice","LINQ siempre es más rápido que cualquier bucle for escrito a mano en cualquier escenario","Where y Select solo funcionan sobre listas ya ordenadas alfabéticamente","No hay ninguna ventaja real, ambos enfoques son idénticos en todos los aspectos",0,"LINQ permite expresar la intención (filtrar y transformar) de forma declarativa y componible, reduciendo código repetitivo de iteración manual y errores comunes asociados, aunque el rendimiento exacto depende del escenario."),
  sqr("Si `IOrderRepository.FindAsync` estuviera implementado con EF Core usando `_db.Orders.Include(o => o.Items).FirstOrDefaultAsync(o => o.Id == id)`, ¿qué problema de rendimiento se evita al acceder después a `order.Items` dentro de `Complete()` si esta usara esa colección?","El problema N+1: sin Include, acceder a order.Items dispararía una consulta adicional por lazy loading; con Include, esa relación ya se cargó en la consulta inicial","Ningún problema; Include nunca afecta el rendimiento de ninguna consulta","Include elimina automáticamente la necesidad de un DbContext","Include convierte la consulta en síncrona, perdiendo los beneficios de async",0,"Usar Include trae la colección relacionada como parte de la consulta inicial (eager loading), evitando que cada acceso a order.Items dispare una consulta SQL adicional por separado (el problema N+1)."),
  sqr("¿Qué mock se necesitaría para verificar en una prueba unitaria que `HandleAsync` llama a `SaveAsync` exactamente una vez tras completar exitosamente la orden, sin usar una base de datos real?","Un mock de IOrderRepository configurado para que FindAsync devuelva una orden pendiente, y luego verificar con Verify que SaveAsync fue llamado una vez","Un fake de HttpClient, porque HandleAsync depende de llamadas HTTP","No se necesita ningún doble de prueba porque HandleAsync no tiene dependencias externas","Un stub de CancellationToken únicamente",0,"Como CompleteOrderHandler depende de IOrderRepository, un mock de esa interfaz (configurando FindAsync para devolver una orden válida) permite verificar la interacción esperada (SaveAsync llamado una vez) sin infraestructura real."),
  sqr("¿Qué capa de una arquitectura limpia debería contener la lógica de `Order.Complete()` (validar el estado antes de transicionar), y por qué no debería estar en el controlador HTTP directamente?","La capa de dominio, para que la regla se aplique consistentemente sin importar el punto de entrada (API HTTP, un job en background, otro servicio), evitando duplicar o saltarse la validación","La capa de presentación, porque los controladores deben concentrar toda la lógica de negocio","La capa de infraestructura, junto con el código de acceso a datos de EF Core","No importa la capa, siempre que compile correctamente",0,"Colocar la regla de negocio en el dominio (Order.Complete()) garantiza que se aplique sin importar desde dónde se invoque, evitando que un controlador HTTP (u otro punto de entrada) olvide validar el estado antes de mutar el objeto."),
  sqr("Si dos solicitudes concurrentes llaman a `HandleAsync` para la misma orden casi simultáneamente, ¿qué mecanismo de EF Core ayudaría a detectar que una de ellas trabajó con datos desactualizados al guardar?","Un token de concurrencia (por ejemplo una columna RowVersion) que provoque DbUpdateConcurrencyException si la fila cambió entre la lectura y el SaveChanges","Ninguno; EF Core no puede detectar condiciones de carrera bajo ninguna circunstancia","AsNoTracking, que previene automáticamente cualquier conflicto de concurrencia","Include, porque carga las relaciones necesarias para evitar condiciones de carrera",0,"Configurar una propiedad como token de concurrencia (RowVersion/Timestamp) permite que EF Core detecte, al guardar, si la fila fue modificada por otra transacción desde que se leyó, lanzando DbUpdateConcurrencyException en vez de sobrescribir datos silenciosamente."),
  sqr("Trampa de entrevista final: ¿es buena práctica que `CompleteOrderHandler` capture genéricamente cualquier `Exception` alrededor de todo `HandleAsync` y simplemente la ignore (catch vacío) para que la API 'nunca falle'?","No; ocultar excepciones indiscriminadamente esconde errores reales (bugs, datos corruptos, fallos de infraestructura) y dificulta el diagnóstico, en vez de manejarlas de forma específica y significativa (o dejarlas propagar a un middleware centralizado de manejo de errores)","Sí, es la mejor práctica recomendada para maximizar la disponibilidad aparente de la API","Sí, porque cualquier excepción no capturada siempre tira el proceso completo sin remedio","No, porque C# no permite declarar un catch vacío bajo ninguna circunstancia",0,"Un catch genérico y vacío ('swallow' de excepciones) oculta problemas reales en vez de resolverlos, generando comportamiento silenciosamente incorrecto; la práctica recomendada es manejar excepciones específicas con sentido, o dejar que un middleware centralizado (como el de ASP.NET Core) las traduzca a respuestas HTTP apropiadas y las registre."),
 ]},
];

export const stepsN09N11: AdvancedStep[] = [...stepsN09, ...stepsN10, ...stepsN11];
